window.NTI=window.NTI||{};(window.NTI.docs=window.NTI.docs||{})["kubernetes-40-the-complete-br-kubernetes-guide"]={"html":"The Complete Kubernetes Guide — Architecture · Namespaces · Workloads · Networking · Labs\n\n\n<a href=\"#toc\">▤ TOC</a>\n\n\n<div class=\"page cover\">\n<div class=\"orb\"></div>\n<div class=\"orb\"></div>\n<div class=\"wheel\">☸️</div>\n<h1 id=\"the-completekubernetes-guide\">THE COMPLETE<br />KUBERNETES GUIDE</h1>\n<div class=\"sub\">Architecture · Namespaces · Workloads · Networking · Labs — one coherent volume, deduplicated and rebuilt from MASTER + k8s 2/k8a. The brain, the muscle, the apartments, the traffic — and the hands-on labs that prove it.</div>\n<div class=\"row\">\n<div class=\"glass\">🚪 API Server<small>the front door</small></div>\n<div class=\"glass\">💾 etcd<small>cluster memory</small></div>\n<div class=\"glass\">🎯 Scheduler<small>placement</small></div>\n<div class=\"glass\">🔄 Controllers<small>reconcile</small></div>\n</div>\n<div class=\"row\">\n<div class=\"glass\">👷 kubelet<small>node agent</small></div>\n<div class=\"glass\">⚙️ Runtime<small>runs containers</small></div>\n<div class=\"glass\">🌐 kube-proxy<small>service networking</small></div>\n<div class=\"glass\">🫛 Pods<small>your apps</small></div>\n</div>\n<div class=\"ver\">K8S KNOWLEDGE BASE · BOOK 01 · DEDUPED &amp; COMPLETE · 2026</div>\n</div>\n\n\n<div class=\"page\">\n<div class=\"pghead\"><span class=\"chip\">📖</span><h2 id=\"contents-click-any-row\">Contents — click any row</h2><span class=\"dbadge\">8 parts · 39 chapters</span></div>\n<div class=\"tocgrid\">\n<div class=\"tocpart\">Part 0 · Orientation</div>\n<a href=\"#ch00\"><span class=\"cb\"></span><span class=\"tnum\">CH 00</span>What is Kubernetes?<span class=\"dots\"></span><span class=\"tp\">p.3</span></a>\n<a href=\"#ch00b\"><span class=\"cb\"></span><span class=\"tnum\">CH 00·b</span>What is Kubernetes? (cont.)<span class=\"dots\"></span><span class=\"tp\">p.4</span></a>\n<div class=\"tocpart\">Part I · The Cluster</div>\n<a href=\"#ch01\"><span class=\"cb\"></span><span class=\"tnum\">CH 01</span>What is a Kubernetes Cluster?<span class=\"dots\"></span><span class=\"tp\">p.4</span></a>\n<a href=\"#ch02\"><span class=\"cb\"></span><span class=\"tnum\">CH 02</span>The Control Plane (Master)<span class=\"dots\"></span><span class=\"tp\">p.5</span></a>\n<a href=\"#ch03\"><span class=\"cb\"></span><span class=\"tnum\">CH 03</span>The Worker Node<span class=\"dots\"></span><span class=\"tp\">p.6</span></a>\n<a href=\"#ch04\"><span class=\"cb\"></span><span class=\"tnum\">CH 04</span>How Master &amp; Worker Communicate<span class=\"dots\"></span><span class=\"tp\">p.7</span></a>\n<div class=\"tocpart\">Part II · See It Work</div>\n<a href=\"#ch05\"><span class=\"cb\"></span><span class=\"tnum\">CH 05</span>Walkthrough — Deploying nginx<span class=\"dots\"></span><span class=\"tp\">p.8</span></a>\n<a href=\"#ch06\"><span class=\"cb\"></span><span class=\"tnum\">CH 06</span>Self-Healing — When a Worker Dies<span class=\"dots\"></span><span class=\"tp\">p.9</span></a>\n<a href=\"#ch07\"><span class=\"cb\"></span><span class=\"tnum\">CH 07</span>Can the Control Plane also be a Worker?<span class=\"dots\"></span><span class=\"tp\">p.10</span></a>\n<a href=\"#ch08\"><span class=\"cb\"></span><span class=\"tnum\">CH 08</span>Master : Worker Ratio &amp; etcd Quorum<span class=\"dots\"></span><span class=\"tp\">p.11</span></a>\n<a href=\"#ch09\"><span class=\"cb\"></span><span class=\"tnum\">CH 09</span>The Diagram Map + Learning Roadmap<span class=\"dots\"></span><span class=\"tp\">p.12</span></a>\n<div class=\"tocpart\">Part III · Namespaces</div>\n<a href=\"#ch10\"><span class=\"cb\"></span><span class=\"tnum\">CH 10</span>Namespaces — The Big Idea<span class=\"dots\"></span><span class=\"tp\">p.13</span></a>\n<a href=\"#ch11\"><span class=\"cb\"></span><span class=\"tnum\">CH 11</span>Names Are Scoped + The Three Superpowers<span class=\"dots\"></span><span class=\"tp\">p.14</span></a>\n<a href=\"#ch12\"><span class=\"cb\"></span><span class=\"tnum\">CH 12</span>Service DNS + Default Namespaces<span class=\"dots\"></span><span class=\"tp\">p.15</span></a>\n<a href=\"#ch13\"><span class=\"cb\"></span><span class=\"tnum\">CH 13</span>The Complete Namespace Picture<span class=\"dots\"></span><span class=\"tp\">p.16</span></a>\n<div class=\"tocpart\">Part IV · Workloads</div>\n<a href=\"#ch14\"><span class=\"cb\"></span><span class=\"tnum\">CH 14</span>ReplicaSet — What Is It?<span class=\"dots\"></span><span class=\"tp\">p.17</span></a>\n<a href=\"#ch15\"><span class=\"cb\"></span><span class=\"tnum\">CH 15</span>Labels, Death &amp; Why Deployment<span class=\"dots\"></span><span class=\"tp\">p.18</span></a>\n<a href=\"#ch16\"><span class=\"cb\"></span><span class=\"tnum\">CH 16</span>The Pod Lifecycle — Owned vs Standalone<span class=\"dots\"></span><span class=\"tp\">p.19</span></a>\n<a href=\"#ch17\"><span class=\"cb\"></span><span class=\"tnum\">CH 17</span>kubectl — The Command Map<span class=\"dots\"></span><span class=\"tp\">p.20</span></a>\n<a href=\"#ch18\"><span class=\"cb\"></span><span class=\"tnum\">CH 18</span>Pod Deep Dive<span class=\"dots\"></span><span class=\"tp\">p.21</span></a>\n<a href=\"#ch19\"><span class=\"cb\"></span><span class=\"tnum\">CH 19</span>Multi-Container Pods<span class=\"dots\"></span><span class=\"tp\">p.22</span></a>\n<a href=\"#ch20\"><span class=\"cb\"></span><span class=\"tnum\">CH 20</span>Deployment — Rolling Updates<span class=\"dots\"></span><span class=\"tp\">p.23</span></a>\n<a href=\"#ch21\"><span class=\"cb\"></span><span class=\"tnum\">CH 21</span>Rollout Commands<span class=\"dots\"></span><span class=\"tp\">p.24</span></a>\n<div class=\"tocpart\">Part V · YAML &amp; Debugging</div>\n<a href=\"#ch22\"><span class=\"cb\"></span><span class=\"tnum\">CH 22</span>YAML Anatomy — The Two Specs<span class=\"dots\"></span><span class=\"tp\">p.25</span></a>\n<a href=\"#ch23\"><span class=\"cb\"></span><span class=\"tnum\">CH 23</span>Debugging 1 — Reading Pod States<span class=\"dots\"></span><span class=\"tp\">p.26</span></a>\n<a href=\"#ch24\"><span class=\"cb\"></span><span class=\"tnum\">CH 24</span>Debugging 2 — The Toolbox<span class=\"dots\"></span><span class=\"tp\">p.27</span></a>\n\n</div>\n<div class=\"lgd\">\n<div><span class=\"dot8\"></span>API Server</div><div><span class=\"dot8\"></span>etcd</div>\n<div><span class=\"dot8\"></span>Scheduler</div><div><span class=\"dot8\"></span>Controllers</div>\n<div><span class=\"dot8\"></span>kubelet</div><div><span class=\"dot8\"></span>Runtime</div>\n<div><span class=\"dot8\"></span>kube-proxy</div><div><span class=\"dot8\"></span>Namespace</div>\n<div><span class=\"dot8\"></span>Secret</div><div><span class=\"dot8\"></span>Pod</div>\n</div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>How to read this book:</b> one spine — <b>User → kubectl → API Server → Admission → Scheduler → Node → kubelet → Runtime</b>. Part 0 orients you, I–II build the picture, III–VI add the depth, VII proves it with your hands, VIII makes it stick.</div></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span>◀ cover · start · <a href=\"#tocb\">contents ▶</a></span><span>Page 2</span></div>\n</div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">📖</span><h2 id=\"contents-continued\">Contents — continued</h2><span class=\"dbadge\">Parts VI–VIII</span></div>\n<div class=\"tocgrid\">\n<div class=\"tocpart\">Part VI · Services &amp; Networking</div>\n<a href=\"#ch25\"><span class=\"cb\"></span><span class=\"tnum\">CH 25</span>NodePort — The Side Entrance<span class=\"dots\"></span><span class=\"tp\">p.28</span></a>\n<a href=\"#ch26\"><span class=\"cb\"></span><span class=\"tnum\">CH 26</span>Service Networking — The Virtual IP<span class=\"dots\"></span><span class=\"tp\">p.29</span></a>\n<a href=\"#ch27\"><span class=\"cb\"></span><span class=\"tnum\">CH 27</span>kube-proxy's Real Job<span class=\"dots\"></span><span class=\"tp\">p.30</span></a>\n<a href=\"#ch28\"><span class=\"cb\"></span><span class=\"tnum\">CH 28</span>Following ONE Packet — 6 Steps<span class=\"dots\"></span><span class=\"tp\">p.31</span></a>\n<div class=\"tocpart\">Part VII · Labs</div>\n<a href=\"#ch29\"><span class=\"cb\"></span><span class=\"tnum\">LAB 1</span>Observe vs Control<span class=\"dots\"></span><span class=\"tp\">p.32</span></a>\n<a href=\"#ch30\"><span class=\"cb\"></span><span class=\"tnum\">LAB 2</span>Scale &amp; Self-Healing<span class=\"dots\"></span><span class=\"tp\">p.33</span></a>\n<a href=\"#ch31\"><span class=\"cb\"></span><span class=\"tnum\">LAB 3</span>Namespaces<span class=\"dots\"></span><span class=\"tp\">p.34</span></a>\n<a href=\"#ch32\"><span class=\"cb\"></span><span class=\"tnum\">LAB 4</span>Rollout &amp; Rollback<span class=\"dots\"></span><span class=\"tp\">p.35</span></a>\n<a href=\"#ch33\"><span class=\"cb\"></span><span class=\"tnum\">LAB 5</span>Taints &amp; Tolerations<span class=\"dots\"></span><span class=\"tp\">p.36</span></a>\n<div class=\"tocpart\">Part VIII · Prove It</div>\n<a href=\"#ch34\"><span class=\"cb\"></span><span class=\"tnum\">QUIZ</span>Self-Check Quiz<span class=\"dots\"></span><span class=\"tp\">p.37</span></a>\n<a href=\"#ch35\"><span class=\"cb\"></span><span class=\"tnum\">KEY</span>Answer Key + Scoring<span class=\"dots\"></span><span class=\"tp\">p.38</span></a>\n<a href=\"#ch36\"><span class=\"cb\"></span><span class=\"tnum\">GLOSS</span>Glossary<span class=\"dots\"></span><span class=\"tp\">p.39</span></a>\n<a href=\"#ch37\"><span class=\"cb\"></span><span class=\"tnum\">CHEAT</span>One-Page Cheat Sheet<span class=\"dots\"></span><span class=\"tp\">p.40</span></a>\n<a href=\"#ch38\"><span class=\"cb\"></span><span class=\"tnum\">FINALE</span>The Map You Can Draw From Memory<span class=\"dots\"></span><span class=\"tp\">p.41</span></a>\n</div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#toc\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch00\">next ▶</a></span><span>Page 3</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 00</span><h2 id=\"what-is-kubernetes\">☸️ What is Kubernetes?</h2><span class=\"dbadge\">🟢 5 MIN · START HERE</span></div>\n<p><b>Kubernetes</b> is an open-source <b>container orchestrator</b>: it takes the containers you define and — across a fleet of machines — <b>deploys them, scales them, heals them, connects them, and updates them without downtime</b>. You describe what you want. It makes reality match. Forever.</p>\n<div class=\"grid3\">\n<div class=\"card center\"><div>📜</div><p><b>The Name</b><br />Greek <i>κυβερνήτης</i> (kybernetes) = <b>helmsman</b> — the one who steers the ship. Hence the wheel logo ☸️ (and the word <i>cybernetics</i>).</p></div>\n<div class=\"card center\"><div>🔢</div><p><b>k8s</b><br />Programmer shorthand: <b>K</b> + the 8 letters in between + <b>s</b>. Pronounced \"K-eights\" — you'll read it a hundred times a day.</p></div>\n<div class=\"card center\"><div>🧬</div><p><b>Lineage</b><br />Born at Google from <b>Borg</b> (its internal cluster manager, ~2003) → open-sourced <b>2014</b> → donated to the <b>CNCF</b> with v1.0 in <b>2015</b>. Written in Go.</p></div>\n</div>\n<h3 id=\"the-problem-it-solves-running-one-container-is-easy-running-a-fleet-is-not\">🤔 The problem it solves — running ONE container is easy; running a fleet is not</h3>\n<div class=\"grid2\">\n<div class=\"card\">\n<div class=\"zlabel\">😩 Without an orchestrator</div>\n<ul>\n<li>💀 A container crashes at 3am → <b>you</b> restart it</li>\n<li>🗺️ Ten machines free — which one takes the new app? <b>you</b> decide</li>\n<li>🕸️ 40 containers need to find each other → hand-written configs</li>\n<li>🎞️ Upgrade from v1 to v2 → downtime, or a hand-rolled script</li>\n<li>📈 Black Friday? Log in and start containers <b>manually</b></li>\n</ul>\n</div>\n<div class=\"card\">\n<div class=\"zlabel\">☸️ With Kubernetes</div>\n<ul>\n<li>🔄 Crash → <b>replaced automatically</b> (reconciliation — CH 06)</li>\n<li>🎯 New app → the <b>Scheduler</b> picks the best node (CH 02)</li>\n<li>🧭 Containers find each other via <b>DNS + Services</b> (CH 12, 26)</li>\n<li>🎬 Upgrades roll out with <b>zero downtime</b> + one-command undo (CH 20–21)</li>\n<li>📈 Scaling = <b>change one number</b> (Lab 2)</li>\n</ul>\n</div>\n</div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>The core idea — declarative, not imperative:</b> you don't write steps (\"<i>start container, then check, then restart…</i>\"). You declare a <b>wish</b> (\"<i>3 replicas of nginx</i>\") and Kubernetes runs a permanent <b>reconciliation loop</b>: watch actual → compare to desired → act. This one idea is the engine behind self-healing, scaling, and rollouts — and it returns on almost every page of this book.</div></div>\n<h3 id=\"what-s-in-the-box\">🎁 What's in the box</h3>\n<div class=\"rowc\">\n<div class=\"kchip\">🔄 Self-healing<small> restarts · replaces</small></div>\n<div class=\"kchip\">📏 Scaling<small> one command</small></div>\n<div class=\"kchip\">🎬 Rollouts + rollback<small> zero downtime</small></div>\n<div class=\"kchip\">🧭 Service discovery + LB<small> built-in DNS</small></div>\n<div class=\"kchip\">🔐 Config &amp; Secrets<small> injected, not baked</small></div>\n<div class=\"kchip\">🗄️ Storage orchestration<small> PVC/PV</small></div>\n</div>\n<p>Industry gravity: every major cloud runs it as a service — <b>GKE</b> (Google) · <b>EKS</b> (AWS) · <b>AKS</b> (Azure) — and it's the CNCF's first graduated project. Learning Kubernetes is learning the <i>operating system of the cloud</i>.</p>\n\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#toc\">▤ TOC</a> · <a href=\"#ch01\">next ▶</a></span><span>Page 3</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 00</span><h2 id=\"what-is-kubernetes-continued\">☸️ What is Kubernetes? — continued</h2><span class=\"dbadge\">🟢 5 MIN · START HERE</span></div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>What Kubernetes is NOT:</b> not a programming language · not a PaaS (it ships <i>building blocks</i>, not opinions) · not a container <b>builder</b> (Docker/CI build images — k8s <i>runs</i> them) · not a runtime itself (it drives one — containerd, CRI-O, CH 03) · not a monitoring system (Prometheus &amp; friends watch it). It's the <b>orchestra conductor</b> 🎻 — it doesn't play a single instrument, but nothing plays without it.</div></div>\n<div class=\"callout co-fun\"><span class=\"ico\">🏺</span><div><b>Heritage flex:</b> Kubernetes didn't invent containers or orchestration — Google had been running <b>billions of containers a week</b> on Borg for a decade. Kubernetes is what happened when they distilled that war story into an open-source project the rest of the world could use. You're learning fifteen years of production scars, organized into an API.</div></div>\n<div class=\"cka\"><span class=\"ico\">🎓</span><div><b>Exam / interview tip:</b> \"What is Kubernetes?\" has a canonical two-beat answer — <b>(1) an open-source container orchestrator, (2) declarative</b>: you declare desired state, it continuously reconciles reality toward it. Add \"descended from Google's Borg\" for bonus credibility.</div></div>\n<p>⏭️ So what does it physically <i>look like</i>? Machines split into a brain and muscle — <a href=\"#ch01\">Chapter 1: What is a Kubernetes Cluster?</a></p>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch00\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch01\">next ▶</a></span><span>Page 4</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 01</span><h2 id=\"what-is-a-kubernetes-cluster\">☸️ What is a Kubernetes Cluster?</h2><span class=\"dbadge\">🟢 4 MIN</span></div>\n<p>A <b>cluster</b> is a collection of machines working together to run your applications. It has exactly two halves:</p>\n<div class=\"rowc\"><div class=\"nb c-navy\">☸️ KUBERNETES CLUSTER<small>the whole herd</small></div></div>\n<div class=\"stem\"></div><div class=\"barwrap\"><div class=\"hbar bar2\"></div></div>\n<div class=\"cols\">\n<div class=\"col\"><div class=\"stub\"></div><div class=\"zone zone-cp\"><div class=\"zlabel\">🧠 Control Plane <span>(Master)</span></div><div class=\"nb c-indigo\">CONTROL PLANE<small>Makes decisions</small></div></div></div>\n<div class=\"col\"><div class=\"stub\"></div><div class=\"zone zone-wk\"><div class=\"zlabel\">💪 Worker Nodes</div><div class=\"nb c-emerald\">WORKER NODES<small>Run applications</small></div></div></div>\n</div>\n<h3 id=\"think-of-it-as\">🧠 + 💪 Think of it as:</h3>\n<div class=\"grid3\">\n<div class=\"think center\"><div>🧠</div><b>Master = Brain</b><br /><span class=\"small\">Thinks, decides, remembers</span></div>\n<div class=\"think center\"><div>💪</div><b>Worker = Muscle</b><br /><span class=\"small\">Lifts, runs, executes</span></div>\n<div class=\"think center\"><div>☸️</div><b>Cluster = Both</b><br /><span class=\"small\">Brain + muscle together</span></div>\n</div>\n<div class=\"callout co-fun\"><span class=\"ico\">🏺</span><div>The modern terminology is <b>Control Plane</b>, not \"Master\". You'll still see <i>master</i> everywhere — because computer science terminology apparently enjoys <b>archaeological preservation</b>. 🏺</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One sentence to remember:</b> Cluster = Control Plane + Worker Nodes. The Control Plane <b>manages</b>. The Workers <b>execute</b>.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#toc\">▤ TOC</a> · <a href=\"#ch02\">next ▶</a></span><span>Page 4</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 02</span><h2 id=\"the-control-plane-master\">🧠 The Control Plane (Master)</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>The Control Plane <b>controls the cluster</b>. It does <b>not</b> normally run your application workloads. Its job:</p>\n<div class=\"rowc\">\n<div class=\"kchip\">📥 Receive requests</div><div class=\"kchip\">💾 Store cluster information</div><div class=\"kchip\">🎯 Decide where Pods should run</div><div class=\"kchip\">👀 Monitor the cluster</div><div class=\"kchip\">✅ Maintain the desired state</div>\n</div>\n<h3 id=\"inside-the-control-plane\">🧩 Inside the Control Plane</h3>\n<div class=\"zone zone-cp\">\n<div class=\"zlabel\">🧠 Control Plane</div>\n<div class=\"rowc\"><div class=\"nb c-blue\">API Server 🚪</div></div>\n<div class=\"stem\"></div><div class=\"barwrap\"><div class=\"hbar\"></div></div>\n<div class=\"cols\">\n<div class=\"col\"><div class=\"stub\"></div><div class=\"nb c-amber\">Scheduler 🎯</div></div>\n<div class=\"col\"><div class=\"stub\"></div><div class=\"nb c-teal\">Controllers 🔄</div></div>\n</div>\n<div class=\"stem\"></div>\n<div class=\"rowc\"><div class=\"nb c-violet\">etcd 💾</div></div>\n</div>\n<h3 id=\"example-you-tell-kubernetes\">🧪 Example — you tell Kubernetes:</h3>\n<div class=\"term\"><span class=\"c\">replicas</span>: <span class=\"y\">3</span></div>\n<p>The Control Plane then figures out:</p>\n<ul>\n<li>🧮 <span>\"I need <b>3 Pods</b>.\"</span></li>\n<li>🗺️ <span>\"<b>Where</b> should they run?\"</span></li>\n<li>👀 <span>\"Are they <b>actually</b> running?\"</span></li>\n<li>💀 <span>\"Did one <b>die</b>?\"</span></li>\n<li>🔁 <span>\"Do I need to <b>create another</b>?\"</span></li>\n</ul>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>The four components, one line each:</b> <b>API Server</b> = the only door 🚪 · <b>etcd</b> = the memory 💾 · <b>Scheduler</b> = the placement officer 🎯 · <b>Controllers</b> = the watchdogs 🔄. Everything else in the cluster talks <i>through</i> the door.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch01\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch03\">next ▶</a></span><span>Page 5</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 03</span><h2 id=\"the-worker-node\">💪 The Worker Node</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>A Worker Node is a machine that <b>actually runs your application workloads</b>.</p>\n<h3 id=\"pods-on-a-worker\">🫛 Pods on a Worker</h3>\n<div class=\"zone zone-wk\">\n<div class=\"zlabel\">💪 Worker Node</div>\n<div class=\"stem\"></div><div class=\"barwrap\"><div class=\"hbar bar3\"></div></div>\n<div class=\"cols\">\n<div class=\"col\"><div class=\"stub\"></div><div class=\"pod\">🫛 Pod 1</div><div class=\"stem\"></div><div class=\"nb c-slate\">📦 Container</div></div>\n<div class=\"col\"><div class=\"stub\"></div><div class=\"pod\">🫛 Pod 2</div><div class=\"stem\"></div><div class=\"nb c-slate\">📦 Container</div></div>\n<div class=\"col\"><div class=\"stub\"></div><div class=\"pod\">🫛 Pod 3</div><div class=\"stem\"></div><div class=\"nb c-slate\">📦 Container</div></div>\n</div>\n</div>\n<h3 id=\"what-s-inside-a-typical-worker-node\">🧰 What's inside a typical Worker Node</h3>\n<div class=\"mtree\">WORKER NODE 💪\n├── <u>kubelet</u> 👷 the node agent\n├── <u>container runtime</u> ⚙️ runs containers\n├── <u>kube-proxy</u> 🌐 service networking\n└── <u>Pods</u> 🫛 your applications</div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>The important idea:</b> the Worker is <b>where your application actually executes</b>. The brain thinks — the muscle lifts.</div></div>\n<div class=\"table-scroll\"><table>\n<tr><th>Component</th><th>Job</th><th>Vibe</th></tr>\n<tr><td><b>kubelet</b></td><td>Manages Pods on this node, reports to the API Server</td><td>👷 Node agent</td></tr>\n<tr><td><b>Container Runtime</b></td><td>Pulls images &amp; runs containers (containerd, CRI-O)</td><td>⚙️ Engine</td></tr>\n<tr><td><b>kube-proxy</b></td><td>Programs Service networking rules on this node</td><td>🌐 Network helper</td></tr>\n<tr><td><b>Pods</b></td><td>Host your containers</td><td>🫛 Application unit</td></tr>\n</table></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch02\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch04\">next ▶</a></span><span>Page 6</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 04</span><h2 id=\"how-master-amp-worker-communicate\">📡 How Master &amp; Worker Communicate</h2><span class=\"dbadge\">🟡 5 MIN · CORE</span></div>\n<p>This is important. The main communication path is the <b>API Server</b> — one door, everything walks through it.</p>\n<div class=\"rowc\">\n<div class=\"nb c-indigo\">🧠 Control Plane<small>API Server 🚪</small></div>\n<span class=\"harr\">──►</span>\n<div class=\"nb c-emerald\">Worker 1<small>kubelet</small></div>\n<div class=\"nb c-emerald\">Worker 2<small>kubelet</small></div>\n<div class=\"nb c-emerald\">Worker 3<small>kubelet</small></div>\n</div>\n<div class=\"dn\">▼             ▼             ▼</div>\n<div class=\"rowc\"><div class=\"pod\">🫛 Pods</div><div class=\"pod\">🫛 Pods</div><div class=\"pod\">🫛 Pods</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">📞</span><div>The <b>kubelet</b> on each worker talks only to the <b>API Server</b>. No worker ever talks to etcd, the Scheduler, or the Controllers directly — everything goes through the front door. 🚪</div></div>\n<div class=\"table-scroll\"><table>\n<tr><th>Who</th><th>Talks to</th><th>Why</th></tr>\n<tr><td><b>kubectl (you)</b></td><td>API Server</td><td>Submit/read everything</td></tr>\n<tr><td><b>kubelet</b></td><td>API Server</td><td>Get assigned Pods · report status</td></tr>\n<tr><td><b>Scheduler</b></td><td>API Server</td><td>Watch unscheduled Pods · write its decisions</td></tr>\n<tr><td><b>Controllers</b></td><td>API Server</td><td>Watch actual state · drive it toward desired</td></tr>\n<tr><td><b>API Server</b></td><td><b>etcd</b></td><td>The <i>only</i> component that touches the memory 💾</td></tr>\n</table></div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Why this design wins:</b> one door = one place for authentication, authorization, and audit. Watch anything, change anything — always through the API.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch03\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch05\">next ▶</a></span><span>Page 7</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 05</span><h2 id=\"walkthrough-deploying-nginx\">🚀 Walkthrough — Deploying nginx</h2><span class=\"dbadge\">🟢 5 MIN</span></div>\n<p>Imagine a cluster with <b>1 Control Plane</b> and <b>3 Workers</b>:</p>\n<div class=\"rowc\">\n<div class=\"nb c-indigo\">🧠 Control Plane<small>192.168.1.10</small></div>\n<span class=\"harr\">──►</span>\n<div class=\"nb c-emerald\">Worker 1<small>.11</small></div>\n<div class=\"nb c-emerald\">Worker 2<small>.12</small></div>\n<div class=\"nb c-emerald\">Worker 3<small>.13</small></div>\n</div>\n<p>You run:</p>\n<div class=\"termbar\"><span></span><span></span><span></span></div>\n<div class=\"term tbr\"><span class=\"p\">$</span> kubectl create deployment nginx <span class=\"y\">--image</span>=nginx <span class=\"y\">--replicas</span>=3\n<span class=\"g\">deployment.apps/nginx created</span></div>\n<h3 id=\"the-flow\">🌊 The flow</h3>\n<div class=\"zone zone-cp\">\n<div class=\"rowc\"><div class=\"kchip\">👤 kubectl</div><span class=\"harr\">──►</span><div class=\"nb c-blue\">API Server 🚪</div></div>\n<div class=\"dn\">▼</div>\n<div class=\"rowc\"><div class=\"nb c-slate\">🧠 Control Plane<small>records desired state</small></div></div>\n<div class=\"dn\">▼</div>\n<div class=\"rowc\"><div class=\"nb c-amber\">Scheduler 🎯<small>picks Nodes</small></div></div>\n<div class=\"stem\"></div><div class=\"barwrap\"><div class=\"hbar\"></div></div>\n<div class=\"cols\">\n<div class=\"col\"><div class=\"stub\"></div><div class=\"nb c-emerald\">Worker 1<small>kubelet runs it</small></div></div>\n<div class=\"col\"><div class=\"stub\"></div><div class=\"nb c-emerald\">Worker 2<small>kubelet runs it</small></div></div>\n<div class=\"col\"><div class=\"stub\"></div><div class=\"nb c-emerald\">Worker 3<small>kubelet runs it</small></div></div>\n</div>\n</div>\n<div class=\"rowc\"><div class=\"pod\">Worker 1 → nginx 🫛</div><div class=\"pod\">Worker 2 → nginx 🫛</div><div class=\"pod\">Worker 3 → nginx 🫛</div></div>\n<div class=\"think center\"><b>🧠 The Control Plane decides.  💪 The Workers execute.</b></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch04\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch06\">next ▶</a></span><span>Page 8</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 06</span><h2 id=\"self-healing-when-a-worker-dies\">🔄 Self-Healing — When a Worker Dies</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>This is where Kubernetes starts <b>earning its paycheck</b>. 💰</p>\n<div class=\"rowc\">\n<div class=\"nb c-red\">Worker 1 ❌</div>\n<div class=\"nb c-emerald\">Worker 2 ✅</div>\n<div class=\"nb c-emerald\">Worker 3 ✅</div>\n</div>\n<p>One of your Pods disappeared. The Control Plane notices a mismatch:</p>\n<div class=\"grid2\">\n<div class=\"card\">\n<div class=\"zlabel\">🎯 Desired</div>\n<div class=\"bar-gauge\"><div>1</div><div>2</div><div>3</div></div>\n<div class=\"zlabel\">👀 Actual</div>\n<div class=\"bar-gauge\"><div>1</div><div>2</div><div></div></div>\n<div class=\"center\">Desired 3 ≠ Actual 2 ❌</div>\n</div>\n<div class=\"card\">\n<div class=\"center\">🔄</div>\n<div class=\"center\">Controllers react</div>\n<p>Kubernetes creates replacement Pods on healthy workers — assuming workload &amp; cluster resources allow it.</p>\n</div>\n</div>\n<h3 id=\"after-reconciliation\">✅ After reconciliation</h3>\n<div class=\"rowc\">\n<div class=\"nb c-red\">Worker 1 ❌</div>\n<div class=\"nb c-emerald\">Worker 2 ✅<small>🫛 nginx · 🫛 nginx</small></div>\n<div class=\"nb c-emerald\">Worker 3 ✅<small>🫛 nginx · 🫛 nginx</small></div>\n</div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>The reconciliation loop is the heart of Kubernetes:</b> <i>watch actual → compare to desired → act → repeat, forever</i>. Nobody \"restored\" anything — the system simply cannot tolerate a mismatch.</div></div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>Honest limits:</b> if the cluster is out of CPU/memory, or all healthy nodes are full, replacements stay <b>Pending</b>. Self-healing repairs state — it doesn't conjure capacity.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch05\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch07\">next ▶</a></span><span>Page 9</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 07</span><h2 id=\"can-the-control-plane-also-be-a-worker\">🤔 Can the Control Plane also be a Worker?</h2><span class=\"dbadge\">🟢 4 MIN</span></div>\n<p><b>Technically yes. In production: no.</b> The mechanism that separates them is a <b>taint</b>.</p>\n<div class=\"grid2\">\n<div class=\"card\">\n<div class=\"zlabel\">🏠 Minikube — yes, by design</div>\n<p>A single-node cluster where <b>one machine is both brain and muscle</b>. The Control-Plane taint is removed so workloads can land there. Perfect for learning.</p>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl get nodes\n<span class=\"y\">NAME       STATUS   ROLES</span>\nminikube   Ready    control-plane,master</div>\n</div>\n<div class=\"card\">\n<div class=\"zlabel\">🏭 Production — never</div>\n<p>Control-Plane nodes carry a taint like <code>node-role.kubernetes.io/control-plane:NoSchedule</code> — the Scheduler <b>refuses to place normal Pods there</b>. The brain is protected.</p>\n<div class=\"term mini\"><span class=\"p\">$</span> kubectl describe node cp1 | <span class=\"c\">grep</span> Taints\n<span class=\"r\">Taints: node-role.kubernetes.io/control-plane:NoSchedule</span></div>\n</div>\n</div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>Why the isolation matters:</b> a runaway workload on a Control-Plane node can starve the API Server or etcd — and then <b>the entire cluster's brain</b> slows or freezes. etcd is especially latency-sensitive.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Remember:</b> \"Control Plane ≠ Worker\" is not a law of nature — it's a <b>taint</b>. Remove the taint and the brain will do deadlifts. (Lab 5 covers taints hands-on.)</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch06\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch08\">next ▶</a></span><span>Page 10</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 08</span><h2 id=\"master-worker-ratio-amp-etcd-quorum\">🗳️ Master : Worker Ratio &amp; etcd Quorum</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>Why does everyone run <b>3 Control Planes</b>? Because etcd (the memory 💾) needs a <b>quorum</b> — a majority of members alive and agreeing — to accept any write.</p>\n<div class=\"zone zone-cp\">\n<div class=\"zlabel\">The quorum math</div>\n<div class=\"mtree\">quorum = <b>floor((n-1)/2) + 1</b> members required\n<span class=\"g\"># of Control Planes → failures tolerated before the cluster freezes:</span>\n1 CP → tolerate <span class=\"r\">0</span> failures  (one crash = frozen)\n3 CP → tolerate <span class=\"u\">1</span> failure   <i>← the production minimum</i>\n5 CP → tolerate <span class=\"u\">2</span> failures\n7 CP → tolerate <span class=\"u\">3</span> failures</div>\n</div>\n<div class=\"table-scroll\"><table>\n<tr><th>Control Planes</th><th>Quorum needs</th><th>Tolerates</th><th>Verdict</th></tr>\n<tr><td>1</td><td>1 of 1</td><td><span class=\"bad\">0</span></td><td>Dev only</td></tr>\n<tr><td>2</td><td>2 of 2</td><td><span class=\"bad\">0</span></td><td><b>Worst choice</b> — same tolerance as 1, double the cost</td></tr>\n<tr><td>3</td><td>2 of 3</td><td><span class=\"ok\">1</span></td><td>✅ Standard production</td></tr>\n<tr><td>5</td><td>3 of 5</td><td><span class=\"ok\">2</span></td><td>Large/critical clusters</td></tr>\n</table></div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>The trap:</b> <b>2 is the worst number.</b> Two members need <i>both</i> alive for quorum — one failure freezes writes, exactly like having one. Even numbers add cost without adding tolerance.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Workers scale independently.</b> The ratio isn't \"1 master per N workers\" — it's <b>3–5 Control Planes</b> (for quorum) plus <i>as many Workers as your workload needs</i>. A lost quorum means the cluster keeps running what's deployed but accepts <b>no new state</b>.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch07\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch09\">next ▶</a></span><span>Page 11</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 09</span><h2 id=\"the-diagram-map-learning-roadmap\">🗺️ The Diagram Map + Learning Roadmap</h2><span class=\"dbadge\">🔵 REFERENCE</span></div>\n<p>Everything from Part I–II on one canvas. If you can redraw this from memory, you own the architecture.</p>\n<div class=\"mtree\"><b>☸️ CLUSTER</b>\n├── <b>🧠 CONTROL PLANE</b> <span class=\"g\">×3 for quorum</span>\n│   ├── <u>API Server</u> 🚪 <span class=\"g\">the only door</span>\n│   ├── <u>etcd</u> 💾 <span class=\"g\">state — API Server's alone</span>\n│   ├── <u>Scheduler</u> 🎯 <span class=\"g\">assigns Pods → Nodes</span>\n│   └── <u>Controllers</u> 🔄 <span class=\"g\">reconcile desired ↔ actual</span>\n└── <b>💪 WORKERS</b>\n    ├── <u>kubelet</u> 👷 <span class=\"g\">agent — talks to API Server</span>\n    ├── <u>Runtime</u> ⚙️ <span class=\"g\">pulls + runs containers</span>\n    ├── <u>kube-proxy</u> 🌐 <span class=\"g\">Service rules</span>\n    └── <u>Pods</u> 🫛</div>\n<h3 id=\"the-learning-order-that-works\">🛤️ The learning order that works</h3>\n<div class=\"road\">\n<div class=\"step\"><span class=\"stepnum\">1</span><span><b>Components</b> — who does what (Parts I–II) · you are here ✅</span></div>\n<div class=\"step\"><span class=\"stepnum\">2</span><span><b>Namespaces</b> — carve logical apartments (Part III)</span></div>\n<div class=\"step\"><span class=\"stepnum\">3</span><span><b>Workloads</b> — ReplicaSet → Deployment → updates (Part IV–V)</span></div>\n<div class=\"step\"><span class=\"stepnum\">4</span><span><b>Networking</b> — how traffic actually reaches a Pod (Part VI)</span></div>\n<div class=\"step\"><span class=\"stepnum\">5</span><span><b>Labs</b> — break things, watch them heal (Part VII)</span></div>\n</div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Study rule:</b> never learn a component without knowing <i>who it talks to</i>. Isolated component lists evaporate; <b>communication maps</b> stick.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch08\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch10\">next ▶</a></span><span>Page 12</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 10</span><h2 id=\"namespaces-the-big-idea\">🗂️ Namespaces — The Big Idea</h2><span class=\"dbadge\">🟢 4 MIN</span></div>\n<p>Without namespaces, one cluster = one giant bucket. Frontend, AI and dev all collide — same names, no boundaries. A namespace is the cluster saying <b>\"I can carve logical apartments inside one building.\"</b></p>\n<div class=\"grid2\">\n<div class=\"card\">\n<div class=\"zlabel\">Problem — one flat bucket</div>\n<div class=\"mtree\">Cluster\n├── pod-a\n├── pod-b  <em>frontend?</em>\n├── pod-c  <em>ai?</em>\n└── svc-a  <span class=\"g\"># who owns what?</span></div>\n</div>\n<div class=\"card\">\n<div class=\"zlabel\">Solution — logical apartments</div>\n<div class=\"mtree\">Cluster\n├── <b>frontend</b> <u>Pods + Services</u>\n├── <b>ai</b>       <u>Pods + Services</u>\n└── <b>dev</b>      <u>Pods + Services</u>\n<span class=\"g\">same nodes, same control plane</span></div>\n</div>\n</div>\n<h3 id=\"when-namespaces-shine\">When namespaces shine</h3>\n<div class=\"grid3\">\n<div class=\"card center\"><div>👥</div><p><b>Teams</b><br />frontend / backend / ai</p></div>\n<div class=\"card center\"><div>🌿</div><p><b>Environments</b><br />dev / staging / prod <span>via namespaces</span></p></div>\n<div class=\"card center\"><div>🧩</div><p><b>Apps</b><br />app-a / app-b isolated, same infra</p></div>\n</div>\n<div class=\"grid2\">\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Namespace = logical isolation</b> — it affects names, RBAC, quotas. It does <b>not</b> carve hardware or network by itself.</div></div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Environment ≠ Namespace.</b> Environment is the concept; namespace is one object you can implement it with (another: separate clusters).</div></div>\n</div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch09\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch11\">next ▶</a></span><span>Page 13</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 11</span><h2 id=\"names-are-scoped-the-three-superpowers\">🏷️ Names Are Scoped + The Three Superpowers</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>A Pod's full identity is <b>namespace + kind + name</b>. So <code>dev/nginx</code> and <code>prod/nginx</code> are two different objects — no collision.</p>\n<div class=\"mtree\">Cluster\n├── <b>dev</b>\n│   └── <u>nginx</u> <em>Pod</em>   ← identity: dev / Pod / nginx\n└── <b>prod</b>\n    └── <u>nginx</u> <em>Pod</em>   ← identity: prod / Pod / nginx</div>\n<h3 id=\"the-three-superpowers-namespaces-unlock\">⚡ The three superpowers namespaces unlock</h3>\n<div class=\"grid3\">\n<div class=\"card\"><div class=\"zlabel\">🪪 RBAC — keys</div><p>\"This team may act <b>only inside frontend</b>.\" Permissions scoped per namespace.</p></div>\n<div class=\"card\"><div class=\"zlabel\">📊 Quotas — budget</div><p>\"ai may use at most <b>4 CPU / 8Gi</b>, 10 Pods.\" A ResourceQuota caps each apartment's totals.</p></div>\n<div class=\"card\"><div class=\"zlabel\">🚧 NetworkPolicy — door rules</div><p>\"Pods in dev may <b>not</b> call prod.\" Traffic rules scoped per namespace.</p></div>\n</div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>Not everything lives in an apartment.</b> <b>Nodes</b>, <b>ClusterRoles</b>, <b>PersistentVolumes</b> and <b>Namespaces themselves</b> are <i>cluster-scoped</i> — <code>kubectl get nodes -n dev</code> silently ignores the <code>-n</code>. Nodes belong to the building, not an apartment.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>The rule:</b> namespaced → identity includes the namespace · cluster-scoped → namespace flags do nothing. <b>Namespaces partition names, not hardware.</b></div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch10\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch12\">next ▶</a></span><span>Page 14</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 12</span><h2 id=\"service-dns-default-namespaces\">🧭 Service DNS + Default Namespaces</h2><span class=\"dbadge\">🟡 5 MIN</span></div>\n<h3 id=\"how-pods-find-each-other-dns\">📫 How Pods find each other: DNS</h3>\n<p>Every Service gets a DNS name built from its namespace — that's how cross-Pod traffic finds its way:</p>\n<div class=\"zone zone-net\">\n<div class=\"rowc\">\n<div class=\"nb c-sky\">nginx-service<small>Service</small></div><span class=\"harr\">──►</span>\n<div class=\"kchip\">nginx-service<b>.frontend</b>.svc.cluster.local</div>\n</div>\n<p>same short name resolves <i>within</i> the same namespace — \"nginx-service\" from inside frontend just works</p>\n</div>\n<div class=\"rowc\">\n<div class=\"nb c-blue\">frontend<small>nginx-service</small></div>\n<span>|</span>\n<div class=\"nb c-violet\">ai<small>nginx-service</small></div>\n<span>← same Service name, two namespaces, zero collision</span>\n</div>\n<h3 id=\"the-namespaces-you-always-have\">📦 The namespaces you always have</h3>\n<div class=\"term\"><span class=\"p\">$</span> kubectl get namespaces\n<span class=\"y\">NAME</span>              STATUS\ndefault           Active   <span class=\"g\"># you land here when you omit -n</span>\nkube-system       Active   <span class=\"g\"># the cluster's own components</span>\nkube-public       Active   <span class=\"g\"># public info</span>\nkube-node-lease   Active   <span class=\"g\"># node heartbeats</span></div>\n<ul>\n<li>📌 <code>kubectl get pods</code> is secretly <code>kubectl get pods -n default</code></li>\n<li>📌 <code>kube-system</code> is where the Control Plane's own Pods live (on kubeadm clusters)</li>\n</ul>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Mailbox rule:</b> \"nginx-service, Apt frontend\" vs \"nginx-service, Apt ai\" — same name, different mailbox, and the post office (DNS + API Server) always delivers correctly.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch11\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch13\">next ▶</a></span><span>Page 15</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 13</span><h2 id=\"the-complete-namespace-picture\">🏢 The Complete Namespace Picture</h2><span class=\"dbadge\">🔵 REFERENCE</span></div>\n<div class=\"mtree\"><b>☸️ CLUSTER</b>\n├── <b>Namespace: frontend</b>  <u>Pods · Services · Quotas</u>\n├── <b>Namespace: ai</b>        <u>Pods · Services · Quotas</u>\n├── <b>Namespace: dev</b>       <u>Pods · Services · Quotas</u>\n│\n└── <b>Nodes</b>  <span class=\"g\"># OUTSIDE every namespace</span>\n    ├── node1  (4 CPU / 8Gi)\n    └── node2  (4 CPU / 8Gi)   <span class=\"g\"># one shared pool</span></div>\n<div class=\"table-scroll\"><table>\n<tr><th>Layer</th><th>Shared across namespaces?</th><th>Notes</th></tr>\n<tr><td><b>Control Plane</b> (API Server, etcd, Scheduler)</td><td>✅ Yes — one per cluster</td><td>A namespace is just a field on objects</td></tr>\n<tr><td><b>Nodes · CPU · Memory · Network</b></td><td>✅ Yes</td><td>Quotas <i>limit</i> usage, they don't carve hardware</td></tr>\n<tr><td><b>Pods · Services · ConfigMaps</b></td><td>❌ No — namespaced</td><td><code>dev/nginx</code> ≠ <code>prod/nginx</code></td></tr>\n</table></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Namespace ≠ separate cluster.</b> Same control plane, same Nodes, same CPU/memory pool. If an exam asks \"is a namespace its own cluster?\" — the answer is a hard <b>NO</b>.</div></div>\n<div class=\"callout co-fun\"><span class=\"ico\">😄</span><div><b>Apartment summary:</b> cluster = building · namespace = apartment · quota = \"max electricity for this apartment\" · RBAC = who holds which keys · Ingress = the front desk routing visitors. One metaphor, whole book.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch12\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch14\">next ▶</a></span><span>Page 16</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 14</span><h2 id=\"replicaset-what-is-it\">🛡️ ReplicaSet — What Is It?</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>A ReplicaSet is <b>the guarantor</b>: it watches a set of Pods that carry specific <b>labels</b>, and keeps their count at the number you asked for. Not one more, not one fewer.</p>\n<div class=\"term\"><span class=\"c\">apiVersion</span>: apps/v1\n<span class=\"c\">kind</span>: ReplicaSet\n<span class=\"c\">metadata</span>:\n  <span class=\"c\">name</span>: nginx-rs\n<span class=\"c\">spec</span>:\n  <span class=\"c\">replicas</span>: <span class=\"y\">3</span>                <span class=\"g\"># ← the promise</span>\n  <span class=\"c\">selector</span>:\n    <span class=\"c\">matchLabels</span>:\n      <span class=\"c\">app</span>: nginx              <span class=\"g\"># ← who it manages</span>\n  <span class=\"c\">template</span>:                    <span class=\"g\"># ← the pod stamp it uses</span>\n    <span class=\"c\">metadata</span>:\n      <span class=\"c\">labels</span>: { <span class=\"c\">app</span>: nginx }  <span class=\"g\"># must match the selector!</span>\n    <span class=\"c\">spec</span>:\n      <span class=\"c\">containers</span>:\n      - <span class=\"c\">name</span>: nginx\n        <span class=\"c\">image</span>: nginx:1.25</div>\n<h3 id=\"how-it-counts\">🔍 How it \"counts\"</h3>\n<ul>\n<li>🔎 <b>Selector</b> — the ReplicaSet claims every Pod whose labels match <code>app: nginx</code></li>\n<li>🧮 <b>Compare</b> — desired 3 vs actual (say) 2</li>\n<li>🔧 <b>Act</b> — create one more Pod from the template (or delete surplus)</li>\n<li>🔁 <b>Repeat</b> — this is just the reconciliation loop again, one level down</li>\n</ul>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>Label match is everything.</b> If the template's labels don't satisfy the selector, the ReplicaSet refuses to start. And any <i>stray</i> Pod with matching labels gets adopted — willingly or not.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>ReplicaSet = labels + count + template.</b> You'll rarely write one by hand — a <b>Deployment</b> creates them for you (CH 15).</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch13\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch15\">next ▶</a></span><span>Page 17</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 15</span><h2 id=\"labels-death-amp-why-deployment\">💀 Labels, Death &amp; Why Deployment</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<div class=\"grid2\">\n<div class=\"card\">\n<div class=\"zlabel\">Standalone Pod dies</div>\n<div class=\"center\">🕳️</div>\n<p><b>Gone. Forever.</b> Nobody holds a copy of the wish — the Pod's spec died with it. This is why \"just run a Pod\" is a demo trick, not a deployment.</p>\n</div>\n<div class=\"card\">\n<div class=\"zlabel\">Owned Pod dies</div>\n<div class=\"center\">🔄</div>\n<p><b>Recreated automatically.</b> The ReplicaSet still holds the template — the mismatch triggers a replacement with a <b>new name</b> (e.g. <code>nginx-rs-x7k2p</code>).</p>\n</div>\n</div>\n<h3 id=\"so-why-isn-t-replicaset-enough-the-ownership-chain\">🪆 So why isn't ReplicaSet enough? The ownership chain</h3>\n<div class=\"mtree\"><b>Deployment</b>  <span class=\"g\">you talk to this one</span>\n└── <b>ReplicaSet v1</b>  <span class=\"g\">manages Pods at image nginx:1.25</span>\n    ├── 🫛 pod\n    ├── 🫛 pod\n    └── 🫛 pod\n<span class=\"g\">change the image →</span> Deployment creates <b>ReplicaSet v2</b>, rolls Pods over <span class=\"g\">← CH 20</span></div>\n<ul>\n<li>🛡️ <b>ReplicaSet</b> answers: \"<i>are the right number of Pods running?</i>\"</li>\n<li>🚀 <b>Deployment</b> answers: \"<i>are they running the <u>right version</u>? — and can we switch versions with zero downtime?</i>\"</li>\n</ul>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Own vs run:</b> a standalone Pod is <i>run</i>; an owned Pod is <i>guaranteed</i>. The Deployment exists because the ReplicaSet can keep count — but it can't change what it's counting <i>without downtime</i>. The Deployment can.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch14\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch16\">next ▶</a></span><span>Page 18</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 16</span><h2 id=\"the-pod-lifecycle-owned-vs-standalone\">👀 The Pod Lifecycle — Owned vs Standalone</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>The five-second experiment that makes ownership real. Two terminals:</p>\n<div class=\"grid2\">\n<div class=\"tabwin\"><div class=\"tabhead\">👀 TAB 1 · WATCH</div><div class=\"tabbody\"><span class=\"p\">$</span> kubectl get pods -w\n<span class=\"y\">NAME           READY  STATUS</span>\nweb-7d9f       0/1    <span class=\"c\">ContainerCreating</span>\nweb-7d9f       1/1    <span class=\"p\">Running</span>\nweb-7d9f       0/1    <span class=\"r\">Terminating</span>\nweb-x7k2p      0/1    <span class=\"c\">ContainerCreating</span>\nweb-x7k2p      1/1    <span class=\"p\">Running</span>  <span class=\"g\"># new name!</span></div></div>\n<div class=\"tabwin\"><div class=\"tabhead\">⚙️ TAB 2 · ACT</div><div class=\"tabbody\"><span class=\"p\">$</span> kubectl delete pod web-7d9f\npod \"web-7d9f\" deleted\n<span class=\"g\"># watch TAB 1: a replacement appears\n# same deployment, brand-new pod name</span></div></div>\n</div>\n<h3 id=\"what-we-just-proved\">🧾 What we just proved</h3>\n<ul>\n<li>✅ The Pod's <b>name is disposable</b> — the ReplicaSet's <b>promise is not</b>.</li>\n<li>✅ Deletion is just another mismatch: desired 1, actual 0 → create.</li>\n<li>❌ A <b>standalone</b> Pod (no owner) deleted = silence. No replacement. No drama.</li>\n</ul>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Status decoding:</b> <span class=\"stbadge st-crea\">ContainerCreating</span> = image pulling + CNI wiring · <span class=\"stbadge st-run\">Running</span> = process up · <span class=\"stbadge st-term\">Terminating</span> = shutting down gracefully · <span class=\"stbadge st-pend\">Pending</span> = not yet placed (CH 23).</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Owned vs standalone is the single most important workload concept.</b> Every \"why did my Pod come back?!\" mystery is answered by: <i>someone owns it</i> — find the ReplicaSet.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch15\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch17\">next ▶</a></span><span>Page 19</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 17</span><h2 id=\"kubectl-the-command-map\">⌨️ kubectl — The Command Map</h2><span class=\"dbadge\">🔵 REFERENCE</span></div>\n<div class=\"table-scroll\"><table>\n<tr><th>Job</th><th>Command</th><th>What it does</th></tr>\n<tr><td><b>Create</b></td><td><code>kubectl create deployment nginx --image=nginx</code></td><td>Imperative quick-start</td></tr>\n<tr><td><code>kubectl apply -f file.yaml</code></td><td>Declarative — the production way</td></tr>\n<tr><td><b>Inspect</b></td><td><code>kubectl get pods/deploy/rs/svc -n ns</code></td><td>List · add <code>-w</code> to watch live · <code>-o wide</code> for Node/IP</td></tr>\n<tr><td><code>kubectl describe pod NAME</code></td><td>Full story — <b>events at the bottom</b></td></tr>\n<tr><td><code>kubectl logs NAME [-c container]</code></td><td>App output · <code>-f</code> follow · <code>--previous</code> for crashed</td></tr>\n<tr><td><b>Debug</b></td><td><code>kubectl exec -it NAME -- sh</code></td><td>Shell inside the container</td></tr>\n<tr><td><code>kubectl get events --sort-by=.lastTimestamp</code></td><td>Cluster-wide recent history</td></tr>\n<tr><td><b>Modify</b></td><td><code>kubectl scale deploy nginx --replicas=5</code></td><td>Change the count</td></tr>\n<tr><td><code>kubectl set image deploy/nginx nginx=nginx:1.26</code></td><td>Trigger a rolling update</td></tr>\n<tr><td><code>kubectl rollout status/undo/history deploy/nginx</code></td><td>Watch / revert / list revisions</td></tr>\n<tr><td><b>Delete</b></td><td><code>kubectl delete pod/dep/ns NAME</code></td><td>Deleting an <b>ns</b> deletes everything inside it ⚠️</td></tr>\n</table></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>The mental model:</b> kubectl is just <b>a client of the API Server</b>. Every command above is an HTTP call to the front door — nothing magical, nothing direct.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch16\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch18\">next ▶</a></span><span>Page 20</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 18</span><h2 id=\"pod-deep-dive\">🫛 Pod Deep Dive</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>The Pod is the <b>smallest deployable unit</b> — not the container. A Pod is a <b>co-located family of containers</b> that share fate.</p>\n<div class=\"zone zone-wk\">\n<div class=\"zlabel\">One Pod = one shared environment</div>\n<div class=\"rowc\"><div class=\"kchip\">🌐 ONE IP address<small> shared by all containers</small></div></div>\n<div class=\"stem\"></div><div class=\"barwrap\"><div class=\"hbar bar2\"></div></div>\n<div class=\"cols\">\n<div class=\"col\"><div class=\"stub\"></div><div class=\"nb c-blue\">📦 app container<small>listens :80</small></div></div>\n<div class=\"col\"><div class=\"stub\"></div><div class=\"nb c-teal\">📦 sidecar<small>reaches app on localhost</small></div></div>\n</div>\n<div class=\"rowc\"><div class=\"kchip\">💾 shared Volume<small> same files, both containers</small></div></div>\n</div>\n<ul>\n<li>🌐 <b>One IP per Pod</b> — containers inside talk via <code>localhost:port</code>, never \"find the other container's IP\"</li>\n<li>💾 <b>Shared volumes</b> — declared in the Pod spec, mounted by any of its containers</li>\n<li>⏳ <b>Shared lifecycle</b> — born together, scheduled together (same Node), die together</li>\n<li>🚫 <b>Never scale \"a container\"</b> — you scale Pods; want more copies → more Pods</li>\n</ul>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>Port clashes are real:</b> two containers in one Pod cannot bind the same port — they literally share the network stack.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>The test for Pod-membership:</b> <i>must these containers live and die together on the same machine?</i> Yes → one Pod. No → separate Pods (and let the Scheduler place them freely).</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch17\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch19\">next ▶</a></span><span>Page 21</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 19</span><h2 id=\"multi-container-pods\">👥 Multi-Container Pods</h2><span class=\"dbadge\">🟡 5 MIN</span></div>\n<p>The classic pattern: the <b>sidecar</b> — a helper container riding along with the app container inside one Pod.</p>\n<div class=\"term\"><span class=\"c\">spec</span>:\n  <span class=\"c\">containers</span>:\n  - <span class=\"c\">name</span>: app\n    <span class=\"c\">image</span>: myapp:2.0\n    <span class=\"c\">volumeMounts</span>:\n    - { <span class=\"c\">name</span>: logs, <span class=\"c\">mountPath</span>: <span class=\"m\">/var/log/app</span> }\n  - <span class=\"c\">name</span>: log-shipper          <span class=\"g\"># the sidecar</span>\n    <span class=\"c\">image</span>: busybox\n    <span class=\"c\">command</span>: [<span class=\"m\">\"sh\"</span>,<span class=\"m\">\"-c\"</span>,<span class=\"m\">\"tail -F /logs/app.log\"</span>]\n    <span class=\"c\">volumeMounts</span>:\n    - { <span class=\"c\">name</span>: logs, <span class=\"c\">mountPath</span>: <span class=\"m\">/logs</span> }   <span class=\"g\"># same volume!</span>\n  <span class=\"c\">volumes</span>:\n  - <span class=\"c\">name</span>: logs\n    <span class=\"c\">emptyDir</span>: {}</div>\n<h3 id=\"good-vs-bad-pod-mates\">⚖️ Good vs bad Pod-mates</h3>\n<div class=\"grid2\">\n<div class=\"card\"><div class=\"zlabel\">✅ Belong together</div><ul><li>📜 app + log shipper (shared files)</li><li>🔐 app + auth proxy (shared localhost)</li><li>🔄 app + config reloader (shared lifecycle)</li></ul></div>\n<div class=\"card\"><div class=\"zlabel\">❌ Don't</div><ul><li>frontend + database (scale &amp; fail independently)</li><li>two unrelated services (one crash restarts both... and they fight over ports)</li></ul></div>\n</div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Heuristic:</b> if the two containers <i>could run on different machines</i>, they belong in <b>different Pods</b>. Pod-mates are glued on purpose — glue is a cost.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch18\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch20\">next ▶</a></span><span>Page 22</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 20</span><h2 id=\"deployment-rolling-updates\">🎞️ Deployment — Rolling Updates</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>Change a Deployment's image and it doesn't rebuild Pods in place — it <b>creates a new ReplicaSet</b> and rolls traffic from old to new, keeping availability the whole time.</p>\n<div class=\"termbar\"><span></span><span></span><span></span></div>\n<div class=\"term tbr\"><span class=\"p\">$</span> kubectl set image deploy/nginx nginx=<span class=\"y\">nginx:1.26</span>\ndeployment.apps/nginx image updated\n<span class=\"p\">$</span> kubectl rollout status deploy/nginx\n<span class=\"g\">Waiting for deployment \"nginx\" rollout to finish...</span>\n<span class=\"p\">deployment \"nginx\" successfully rolled out</span></div>\n<h3 id=\"what-actually-happened\">🪆 What actually happened</h3>\n<div class=\"mtree\"><b>Deployment nginx</b>\n├── <b>ReplicaSet v2</b> <em>nginx:1.26</em>   <span class=\"g\">scales 0 → 3 👆</span>\n│   └── 🫛 🫛 🫛  <span class=\"g\">new Pods replace old</span>\n└── <s>ReplicaSet v1</s> <em>nginx:1.25</em>   <span class=\"g\">scales 3 → 0 👇 (kept for rollback)</span></div>\n<ul>\n<li>⚖️ The Controller walks the count: add a v2 Pod → remove a v1 Pod → repeat</li>\n<li>📉 Service selectors keep pointing at labels — traffic slides over automatically</li>\n<li>🗄️ v1's ReplicaSet is <i>retained</i> (scaled to 0) — that's your rollback insurance (CH 21)</li>\n</ul>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Zero downtime is the point:</b> at every instant, enough healthy Pods serve traffic. The Deployment turned \"risky big-bang upgrade\" into \"boring arithmetic.\"</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch19\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch21\">next ▶</a></span><span>Page 23</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 21</span><h2 id=\"rollout-commands\">⏪ Rollout Commands</h2><span class=\"dbadge\">🟢 4 MIN</span></div>\n<div class=\"termbar\"><span></span><span></span><span></span></div>\n<div class=\"term tbr\"><span class=\"p\">$</span> kubectl rollout history deploy/nginx\n<span class=\"y\">REVISION  CHANGE-CAUSE</span>\n1         <span class=\"g\">&lt;none&gt;</span>\n2         <span class=\"g\">nginx:1.26</span>\n<span class=\"p\">$</span> kubectl rollout undo deploy/nginx\ndeployment.apps/nginx rolled back\n<span class=\"p\">$</span> kubectl rollout status deploy/nginx\n<span class=\"p\">successfully rolled out</span>  <span class=\"g\"># ← back on :1.25</span></div>\n<ul>\n<li>📊 <code>rollout status</code> — watch a rollout finish (script-friendly)</li>\n<li>🗂️ <code>rollout history</code> — every revision is just an old ReplicaSet with a number</li>\n<li>⏪ <code>rollout undo</code> — flip back to the previous template · <code>--to-revision=1</code> to pick</li>\n<li>🗄️ <code>revisionHistoryLimit: 3</code> — how many old ReplicaSets to keep (default 10)</li>\n</ul>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>Undo doesn't rewind time</b> — it creates a <b>new revision</b> (v3) with v1's template. History only moves forward; the ReplicaSet list is the audit trail.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>The rollout trilogy</b> — <code>status</code> / <code>history</code> / <code>undo</code> — is the exam's favorite Deployment command set. Learn it as one unit.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch20\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch22\">next ▶</a></span><span>Page 24</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 22</span><h2 id=\"yaml-anatomy-the-two-specs\">📜 YAML Anatomy — The Two Specs</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>Every Kubernetes manifest is the same envelope: <b>apiVersion · kind · metadata · spec</b>. The \"wish\" lives in the spec.</p>\n<div class=\"table-scroll\"><table>\n<tr><th>Field</th><th>Meaning</th><th>Example</th></tr>\n<tr><td><code>apiVersion</code></td><td>Which API group/version serves this kind</td><td><code>v1</code> (Pod) · <code>apps/v1</code> (Deployment)</td></tr>\n<tr><td><code>kind</code></td><td>What object you want</td><td><code>Pod</code>, <code>Service</code>, <code>Deployment</code></td></tr>\n<tr><td><code>metadata</code></td><td>Name · namespace · labels</td><td><code>name: nginx</code></td></tr>\n<tr><td><code>spec</code></td><td><b>The desired state</b></td><td>replicas, containers, ports…</td></tr>\n</table></div>\n<h3 id=\"the-two-specs-mystery-deployment\">🪆 The Two-Specs Mystery (Deployment)</h3>\n<div class=\"mtree\"><span class=\"c\">spec</span>:                      <span class=\"g\"># the DEPLOYMENT's wish</span>\n  <span class=\"c\">replicas</span>: <span class=\"y\">3</span>\n  <span class=\"c\">selector</span>: …\n  <span class=\"c\">template</span>:               <span class=\"g\"># a whole Pod hiding inside!</span>\n    <span class=\"c\">metadata</span>: <span class=\"c\">labels</span>: …\n    <span class=\"c\">spec</span>:                <span class=\"g\"># ← the POD's wish (spec inside spec)</span>\n      <span class=\"c\">containers</span>: …</div>\n<ul>\n<li>🧠 <b>Outer spec</b> = what the Deployment manages: count, selector, template</li>\n<li>🫛 <b>Inner spec</b> (<code>spec.template.spec</code>) = the actual Pod: images, ports, env, resources</li>\n<li>🔁 <code>spec.template</code> is the <b>cookie cutter</b> — the ReplicaSet stamps Pods from it; change anything inside and you trigger a rollout (CH 20)</li>\n</ul>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Indentation is structure in YAML.</b> The most common manifest bug is writing the Pod spec at the wrong nesting level — and the API Server answers with a confusing validation error. Count your two spaces.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch21\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch23\">next ▶</a></span><span>Page 25</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 23</span><h2 id=\"debugging-1-reading-pod-states\">🩺 Debugging 1 — Reading Pod States</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>The STATUS column is a diagnosis. Each state tells you <i>which stage</i> failed — before you run a single command.</p>\n<div class=\"table-scroll\"><table>\n<tr><th>Status</th><th>Meaning</th><th>Classic cause</th><th>First move</th></tr>\n<tr><td><span class=\"stbadge st-pend\">Pending</span></td><td>Accepted, not placed</td><td>Not enough CPU/mem · taints · PVC pending</td><td><code>describe pod</code> → events</td></tr>\n<tr><td><span class=\"stbadge st-crea\">ContainerCreating</span></td><td>Placed, pulling/wiring</td><td>Normal for seconds; stuck = image/CNI issue</td><td><code>describe pod</code> → events</td></tr>\n<tr><td><span class=\"stbadge st-term\">ImagePullBackOff</span></td><td>Can't fetch image</td><td>Typo in tag · private registry, no secret</td><td>Check image name &amp; pull secret</td></tr>\n<tr><td><span class=\"stbadge st-term\">CrashLoopBackOff</span></td><td>Starts, dies, repeats</td><td>App crashes on boot — bad config, missing env</td><td><code>logs --previous</code></td></tr>\n<tr><td><span class=\"stbadge st-run\">Running</span></td><td>Process is up</td><td>— (not necessarily <i>healthy</i> — that's probes)</td><td>Test the endpoint</td></tr>\n<tr><td><span class=\"stbadge st-comp\">Completed</span></td><td>Finished &amp; exited 0</td><td>Job finished — normal for Jobs, odd for servers</td><td>Expected? done ✅</td></tr>\n</table></div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>The backoff family:</b> <code>ImagePullBackOff</code> and <code>CrashLoopBackOff</code> are not errors <i>of</i> Kubernetes — they're Kubernetes <i>retrying</i> after your app/image failed. The real error is one layer deeper, in the events or logs.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Memory hook:</b> Pending = the <b>Scheduler</b> said no · ImagePull = the <b>Registry</b> said no · CrashLoop = the <b>App</b> said no. Three different culprits, three different rooms to search.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch22\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch24\">next ▶</a></span><span>Page 26</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 24</span><h2 id=\"debugging-2-the-toolbox\">🧰 Debugging 2 — The Toolbox</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<div class=\"term\"><span class=\"p\">$</span> kubectl describe pod web-x7k2p        <span class=\"g\"># 1 · full biography…</span>\n  <span class=\"y\">Events:</span>                                   <span class=\"g\"># …always read the BOTTOM</span>\n   <span class=\"r\">Failed to pull image \"nginx:1.99\"</span>\n<span class=\"p\">$</span> kubectl logs web-x7k2p --previous       <span class=\"g\"># 2 · crashed container's last words</span>\n<span class=\"r\">panic: missing REQUIRED_DB_PASSWORD</span>\n<span class=\"p\">$</span> kubectl exec -it web-x7k2p -- sh       <span class=\"g\"># 3 · go inside</span>\n<span class=\"p\">$</span> kubectl get events --sort-by=<span class=\"y\">.lastTimestamp</span>  <span class=\"g\"># 4 · cluster timeline</span></div>\n<div class=\"grid2\">\n<div class=\"card\"><div class=\"zlabel\">describe — the biography</div><p>Config as the cluster sees it, plus the <b>Events block at the bottom</b> — the single most information-dense place in debugging.</p></div>\n<div class=\"card\"><div class=\"zlabel\">logs --previous — the autopsy</div><p>CrashLoopBackOff kills the evidence — <code>--previous</code> reads the <b>last dead container's</b> output. Forgetting this flag = reading a fresh empty log and panicking.</p></div>\n</div>\n<h3 id=\"the-4-step-playbook-in-order\">🎯 The 4-step playbook (in order)</h3>\n<div class=\"road\">\n<div class=\"step\"><span class=\"stepnum\">1</span><span><b>get pods</b> — read the STATUS column (CH 23 table)</span></div>\n<div class=\"step\"><span class=\"stepnum\">2</span><span><b>describe pod</b> — events at the bottom name the failing stage</span></div>\n<div class=\"step\"><span class=\"stepnum\">3</span><span><b>logs --previous</b> — the app's own error message</span></div>\n<div class=\"step\"><span class=\"stepnum\">4</span><span><b>exec -it -- sh</b> — poke around inside: DNS, env, files, curl</span></div>\n</div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>90% of debugging is reading.</b> The cluster narrates its own failures — through events and logs — if you ask in the right order.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch23\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch25\">next ▶</a></span><span>Page 27</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 25</span><h2 id=\"nodeport-the-side-entrance\">🚪 NodePort — The Side Entrance</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>ClusterIPs are invisible from outside the cluster. <b>NodePort</b> punches a hole: every Node opens one high port and forwards it to your Service.</p>\n<div class=\"term\"><span class=\"c\">apiVersion</span>: v1\n<span class=\"c\">kind</span>: Service\n<span class=\"c\">metadata</span>:\n  <span class=\"c\">name</span>: nginx-svc\n<span class=\"c\">spec</span>:\n  <span class=\"c\">type</span>: <span class=\"y\">NodePort</span>          <span class=\"g\"># default is ClusterIP</span>\n  <span class=\"c\">selector</span>:\n    <span class=\"c\">app</span>: nginx\n  <span class=\"c\">ports</span>:\n  - <span class=\"c\">port</span>: <span class=\"y\">80</span>              <span class=\"g\"># inside the cluster</span>\n    <span class=\"c\">targetPort</span>: <span class=\"y\">80</span>        <span class=\"g\"># container's port</span>\n    <span class=\"c\">nodePort</span>: <span class=\"y\">30080</span>       <span class=\"g\"># outside — or omit &amp; let k8s pick</span></div>\n<div class=\"zone zone-net\">\n<div class=\"zlabel\">The path in</div>\n<div class=\"rowc\">\n<div class=\"kchip\">🌍 User</div><span class=\"harr\">──►</span>\n<div class=\"nb c-emerald\">ANY node<small>:30080</small></div><span class=\"harr\">──►</span>\n<div class=\"nb c-sky\">Service<small>ClusterIP rules</small></div><span class=\"harr\">──►</span>\n<div class=\"pod\">🫛 Pod :80</div>\n</div>\n<p>\"ANY node\" is the superpower — even a Node with <b>no nginx Pod</b> opens the door and forwards across.</p>\n</div>\n<ul>\n<li>📏 Valid range: <b>30000–32767</b> (omit <code>nodePort</code> and one is auto-assigned)</li>\n<li>🔓 Every Node gets the same port — hit <code>192.168.1.11:30080</code> or <code>.13:30080</code>, same result</li>\n</ul>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>NodePort is for demos &amp; edge cases</b> — raw ports, no load balancing across nodes, no TLS story. Production rides <b>Ingress</b> (Book 03 😉).</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch24\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch26\">next ▶</a></span><span>Page 28</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 26</span><h2 id=\"service-networking-the-virtual-ip\">🎭 Service Networking — The Virtual IP</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>Here's the trick nobody tells you: the ClusterIP your Service owns is a <b>lie</b>. Nothing is listening on it. No process holds it. It's a <b>virtual IP (VIP)</b> — and that's the elegance.</p>\n<div class=\"zone zone-net\">\n<div class=\"zlabel\">Russian dolls — where the VIP really goes</div>\n<div class=\"rowc\">\n<div class=\"nb c-sky\">10.96.0.50<small>the VIP — a fiction</small></div>\n<span class=\"harr\">──► DNAT ──►</span>\n<div class=\"nb c-cyan\">10.244.1.5<small>a real Pod IP</small></div>\n</div>\n<p>packets \"to the VIP\" are rewritten <b>in transit</b> to a real Pod — the VIP never terminates anything</p>\n</div>\n<div class=\"mtree\">Address ranges — separate drawers:\nService CIDR   <b>10.96.0.0/12</b>  <span class=\"g\"># VIPs live here (fake, routable only via rules)</span>\nPod CIDR       <b>10.244.0.0/16</b> <span class=\"g\"># real Pod IPs (per-node slices)</span></div>\n<ul>\n<li>🚫 You can't <code>ping</code> a ClusterIP — nothing answers; the rules only rewrite packets <i>passing through</i></li>\n<li>🎭 Pods died and got new IPs? Nobody notices — everyone still dials the VIP</li>\n<li>🧮 The ranges <b>must not overlap</b> — two drawers, zero confusion</li>\n</ul>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>The Service is a stable illusion:</b> an eternal name + eternal IP in front of a set of mortals (Pods) that churn constantly. The illusion is maintained by <b>kube-proxy</b> — next chapter.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch25\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch27\">next ▶</a></span><span>Page 29</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 27</span><h2 id=\"kube-proxy-s-real-job\">🕸️ kube-proxy's Real Job</h2><span class=\"dbadge\">🟡 6 MIN · CORE</span></div>\n<p>kube-proxy does <b>not</b> forward a single packet. Its entire job is two verbs: <b>watch &amp; program</b>.</p>\n<div class=\"grid2\">\n<div class=\"card\"><div class=\"zlabel\">❌ What it does NOT do</div><ul><li>Sit in the traffic path</li><li>Proxy connections through itself</li><li>Touch Pod-to-Pod traffic</li></ul></div>\n<div class=\"card\"><div class=\"zlabel\">✅ What it DOES</div><ul><li><b>Watch</b> the API Server: Services + Endpoints</li><li><b>Program</b> iptables/IPVS rules on <i>its</i> node</li><li>Re-program the instant Pods change</li></ul></div>\n</div>\n<h3 id=\"the-rules-it-writes-iptables-dnat\">🪄 The rules it writes (iptables + DNAT)</h3>\n<div class=\"term mini\"><span class=\"g\"># conceptually, on every node:</span>\n<span class=\"y\">if</span> dst == 10.96.0.50:80 <span class=\"g\"># the VIP</span>\n  <span class=\"y\">then</span> rewrite dst → 10.244.1.5:80  <span class=\"g\"># pick an endpoint (random)</span>\n  <span class=\"y\">else if</span> … next endpoint <span class=\"g\"># (rule set balances across all)</span></div>\n<div class=\"callout co-ok\"><span class=\"ico\">✨</span><div><b>The Illusion, resolved:</b> a Pod dies → Endpoints object updates → every node's kube-proxy rewrites its rules → the <b>VIP never moved</b>. Stability on the outside, churn on the inside, and the packets never knew.</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>One-liner for exams:</b> <i>kube-proxy watches Services/Endpoints and programs packet-rewriting rules on every node — it never forwards traffic itself.</i></div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch26\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch28\">next ▶</a></span><span>Page 30</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CH 28</span><h2 id=\"following-one-packet-6-steps\">📦 Following ONE Packet — 6 Steps</h2><span class=\"dbadge\">🔵 FINALE · CORE</span></div>\n<p>A Pod runs <code>curl nginx-svc</code>. Follow the single packet:</p>\n<div>\n<div class=\"road\">\n<div class=\"step\"><span class=\"stepnum\">1</span><span><b>DNS</b> — <code>nginx-svc</code> resolves to the VIP <code>10.96.0.50</code> · CoreDNS answered from the Service's namespace</span></div>\n<div class=\"step\"><span class=\"stepnum\">2</span><span><b>Send</b> — Pod sends to the VIP (nothing is there — remember CH 26) · dest: 10.96.0.50:80</span></div>\n<div class=\"step\"><span class=\"stepnum\">3</span><span><b>DNAT</b> — the node's iptables rules rewrite the destination → a real Pod IP: <code>10.244.1.5:80</code></span></div>\n<div class=\"step\"><span class=\"stepnum\">4</span><span><b>Route</b> — same node → direct delivery; different node → CNI overlay carries it</span></div>\n<div class=\"step\"><span class=\"stepnum\">5</span><span><b>Receive</b> — the Pod sees a normal packet addressed to <i>its own</i> IP · it replies</span></div>\n<div class=\"step\"><span class=\"stepnum\">6</span><span><b>Return</b> — conntrack rewrites the reply back through the VIP — the client believes it talked to 10.96.0.50 the whole time 🎩</span></div>\n</div>\n</div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>The entire machine in one sentence:</b> DNS gives you a stable fake IP; kube-proxy's rules secretly rewrite it to a mortal Pod; conntrack makes the lie symmetric. <b>That's Service networking — everything else is detail.</b></div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch27\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch29\">labs ▶</a></span><span>Page 31</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 1</span><h2 id=\"observe-vs-control\">🔬 Observe vs Control</h2><span class=\"dbadge\">🟠 15 MIN · HANDS-ON</span></div>\n<div class=\"grid2\">\n<div class=\"tabwin\"><div class=\"tabhead\">👀 TAB 1 · OBSERVE</div><div class=\"tabbody\"><span class=\"p\">$</span> kubectl get deployments -w\n<span class=\"p\">$</span> kubectl get pods -w\n<span class=\"p\">$</span> kubectl get rs -w</div></div>\n<div class=\"tabwin\"><div class=\"tabhead\">⚙️ TAB 2 · CONTROL</div><div class=\"tabbody\"><span class=\"p\">$</span> kubectl create deploy web --image=nginx --replicas=2\n<span class=\"p\">$</span> kubectl delete pod &lt;pod-name&gt;\n<span class=\"p\">$</span> kubectl scale deploy web --replicas=4</div></div>\n</div>\n<div class=\"labstep\"><div>STEP 1 · Create</div>\n<div class=\"labcols\">\n<div><div class=\"labtag\">⚙️ RUN</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl create deployment web --image=nginx --replicas=2\n<span class=\"g\">deployment.apps/web created</span></div></div>\n<div><div class=\"labtag\">👀 EXPECTED in TAB 1</div><div class=\"term mini\"><span class=\"y\">web</span>  2/2  <span class=\"p\">READY</span>\nweb-<span class=\"c\">aaaaa</span>  1/1  Running\nweb-<span class=\"c\">bbbbb</span>  1/1  Running</div></div>\n</div></div>\n<div class=\"labstep\"><div>STEP 2 · Kill a Pod</div>\n<div class=\"labcols\">\n<div><div class=\"labtag\">⚙️ RUN</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl delete pod web-aaaaa\n<span class=\"g\">pod \"web-aaaaa\" deleted</span></div></div>\n<div><div class=\"labtag\">👀 EXPECTED</div><div class=\"term mini\">web-aaaaa  <span class=\"r\">Terminating</span>\nweb-<span class=\"c\">ccccc</span>  <span class=\"c\">ContainerCreating</span>\nweb-ccccc  <span class=\"p\">Running</span>  <span class=\"g\"># replacement!</span></div></div>\n</div></div>\n<div class=\"labstep\"><div>STEP 3 · What we proved</div>\n<p>A ReplicaSet owns the Pods → deletion is a mismatch, not a tragedy. The <b>name</b> died; the <b>promise</b> didn't. (Standalone pods: <code>kubectl run p1 --image=nginx</code> then delete it — silence. Try it.)</p></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch28\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch30\">next ▶</a></span><span>Page 32</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 2</span><h2 id=\"scale-amp-self-healing\">📏 Scale &amp; Self-Healing</h2><span class=\"dbadge\">🟠 10 MIN · HANDS-ON</span></div>\n<div class=\"labstep\"><div>STEP 1 · Scale to 5</div>\n<div class=\"labcols\">\n<div><div class=\"labtag\">⚙️ RUN</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl scale deploy web --replicas=5\n<span class=\"g\">deployment.apps/web scaled</span></div></div>\n<div><div class=\"labtag\">👀 EXPECTED</div><div class=\"term mini\">three new pods\n<span class=\"c\">ContainerCreating → Running</span>\n<span class=\"g\">total: 5/5</span></div></div>\n</div></div>\n<div class=\"labstep\"><div>STEP 2 · Delete two at once</div>\n<div class=\"labcols\">\n<div><div class=\"labtag\">⚙️ RUN</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl delete pod web-ccccc web-ddddd</div></div>\n<div><div class=\"labtag\">👀 EXPECTED</div><div class=\"term mini\"><span class=\"g\"># two replacements appear\n# concurrently, new random names</span>\nback to <span class=\"p\">5/5</span> in seconds</div></div>\n</div></div>\n<div class=\"labstep\"><div>STEP 3 · The edge — starve it</div>\n<div class=\"labcols\">\n<div><div class=\"labtag\">⚙️ RUN</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl scale deploy web --replicas=<span class=\"y\">50</span>\n<span class=\"p\">$</span> kubectl get pods</div></div>\n<div><div class=\"labtag\">👀 YOU'LL SEE</div><div class=\"term mini\">many pods stuck\n<span class=\"r\">Pending</span>  <span class=\"g\"># not enough cluster CPU</span></div></div>\n</div>\n<p><b>The lesson:</b> self-healing repairs <i>state</i>, not <i>capacity</i>. Scale back down: <code>kubectl scale deploy web --replicas=2</code>.</p></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Scale is just editing the promise.</b> The ReplicaSet reconciles upward and downward — surplus Pods get terminated, deficits get filled. Same loop, both directions.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch29\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch31\">next ▶</a></span><span>Page 33</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 3</span><h2 id=\"namespaces\">🗂️ Namespaces</h2><span class=\"dbadge\">🟠 10 MIN · HANDS-ON</span></div>\n<div class=\"labstep\"><div>STEP 1 · Same name, two apartments</div>\n<div class=\"labcols\">\n<div><div class=\"labtag\">⚙️ RUN</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl create ns dev\n<span class=\"p\">$</span> kubectl run nginx --image=nginx -n dev\n<span class=\"p\">$</span> kubectl run nginx --image=nginx</div></div>\n<div><div class=\"labtag\">👀 EXPECTED</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl get pods -A | <span class=\"c\">grep</span> nginx\n<span class=\"y\">default  </span> nginx  Running\n<span class=\"y\">dev      </span> nginx  Running\n<span class=\"g\"># two different pods, zero collision</span></div></div>\n</div></div>\n<div class=\"labstep\"><div>STEP 2 · Namespace flags matter</div>\n<div class=\"labcols\">\n<div><div class=\"labtag\">⚙️ RUN</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl get pods          <span class=\"g\"># default only</span>\n<span class=\"p\">$</span> kubectl get pods -n dev    <span class=\"g\"># dev only</span>\n<span class=\"p\">$</span> kubectl get pods -A        <span class=\"g\"># everything</span></div></div>\n<div><div class=\"labtag\">👀 NOTE</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl get nodes -n dev\n<span class=\"g\"># same node list — -n is IGNORED\n# nodes are cluster-scoped!</span></div></div>\n</div></div>\n<div class=\"labstep\"><div>STEP 3 · The cascade ⚠️</div>\n<div class=\"labcols\">\n<div><div class=\"labtag\">⚙️ RUN</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl delete ns dev\n<span class=\"g\">namespace \"dev\" deleted</span></div></div>\n<div><div class=\"labtag\">👀 EXPECTED</div><div class=\"term mini\"><span class=\"g\"># everything inside dev is\n# terminated and removed —\n# the pod included</span></div></div>\n</div></div>\n<div class=\"callout co-warn\"><span class=\"ico\">⚠️</span><div><b>Deleting a namespace deletes EVERYTHING in it.</b> There is no trash can, no undo. In production, some teams even pin RBAC so only admins can delete namespaces.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch30\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch32\">next ▶</a></span><span>Page 34</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 4</span><h2 id=\"rollout-amp-rollback\">🎞️ Rollout &amp; Rollback</h2><span class=\"dbadge\">🟠 12 MIN · HANDS-ON</span></div>\n<div class=\"labstep\"><div>STEP 1 · Upgrade</div>\n<div class=\"labcols\">\n<div><div class=\"labtag\">⚙️ RUN</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl set image deploy web nginx=<span class=\"y\">nginx:1.26</span>\n<span class=\"p\">$</span> kubectl rollout status deploy web</div></div>\n<div><div class=\"labtag\">👀 EXPECTED</div><div class=\"term mini\"><span class=\"g\">Waiting for deployment…</span>\n<span class=\"p\">successfully rolled out</span>\n<span class=\"p\">$</span> kubectl get rs\n<span class=\"g\"># two RS: old 0, new 2</span></div></div>\n</div></div>\n<div class=\"labstep\"><div>STEP 2 · Ship a broken tag</div>\n<div class=\"labcols\">\n<div><div class=\"labtag\">⚙️ RUN</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl set image deploy web nginx=<span class=\"r\">nginx:1.99</span>\n<span class=\"p\">$</span> kubectl rollout status deploy web</div></div>\n<div><div class=\"labtag\">👀 EXPECTED</div><div class=\"term mini\"><span class=\"r\">Waiting… 1 unavailable</span>\n<span class=\"p\">$</span> kubectl get pods\n<span class=\"g\">one pod in ImagePullBackOff\nOLD pods still running!</span></div></div>\n</div></div>\n<div class=\"labstep\"><div>STEP 3 · Roll back</div>\n<div class=\"labcols\">\n<div><div class=\"labtag\">⚙️ RUN</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl rollout undo deploy web\n<span class=\"p\">$</span> kubectl rollout history deploy web</div></div>\n<div><div class=\"labtag\">👀 EXPECTED</div><div class=\"term mini\"><span class=\"p\">successfully rolled out</span>\n<span class=\"g\"># bad pod terminated, good ones back\n# history shows a NEW revision (v3)</span></div></div>\n</div></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>The safety net is structural:</b> a bad rollout can never take down the old version — the Deployment only removes old Pods once new ones are Ready. Broken tag? The cluster waits, old version serves, you type <code>undo</code>.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch31\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch33\">next ▶</a></span><span>Page 35</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">LAB 5</span><h2 id=\"taints-amp-tolerations\">🚧 Taints &amp; Tolerations</h2><span class=\"dbadge\">🟠 15 MIN · HANDS-ON</span></div>\n<div class=\"labstep\"><div>STEP 1 · Taint AFTER the Pod exists</div>\n<div class=\"labcols\">\n<div><div class=\"labtag\">⚙️ RUN</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl taint node <span class=\"y\">&lt;node&gt;</span> env=prod:NoSchedule\n<span class=\"p\">$</span> kubectl scale deploy web --replicas=4</div></div>\n<div><div class=\"labtag\">👀 EXPECTED</div><div class=\"term mini\"><span class=\"g\"># existing pods keep running\n# NEW 4th pod → Pending</span>\n<span class=\"r\">0/1 Nodes available</span>\n<span class=\"g\">…taint…that pod tolerates not</span></div></div>\n</div>\n<p><b>Key insight:</b> <span class=\"stbadge st-run\">NoSchedule</span> only gates <i>new</i> placements — it never evicts.</p></div>\n<div class=\"labstep\"><div>STEP 2 · Rescue with a toleration</div>\n<div class=\"term mini\"><span class=\"c\">spec</span>:\n  <span class=\"c\">tolerations</span>:\n  - <span class=\"c\">key</span>: env\n    <span class=\"c\">operator</span>: <span class=\"y\">Equal</span>\n    <span class=\"c\">value</span>: prod\n    <span class=\"c\">effect</span>: NoSchedule   <span class=\"g\"># pod may now LAND on the tainted node</span></div>\n<p>Apply → the Pending pod schedules immediately. <b>Taint = the lock. Toleration = the key.</b></p></div>\n<div class=\"labstep\"><div>STEP 3 · NoExecute — the eviction</div>\n<div class=\"labcols\">\n<div><div class=\"labtag\">⚙️ RUN</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl taint node <span class=\"y\">&lt;node&gt;</span> env=prod:<span class=\"r\">NoExecute</span></div></div>\n<div><div class=\"labtag\">👀 EXPECTED</div><div class=\"term mini\"><span class=\"g\"># non-tolerating pods on that\n# node get EVICTED — now</span></div></div>\n</div></div>\n<div class=\"table-scroll\"><table>\n<tr><th>Effect</th><th>Existing Pods</th><th>New Pods</th></tr>\n<tr><td><span class=\"stbadge st-run\">NoSchedule</span></td><td>stay</td><td>blocked (unless tolerated)</td></tr>\n<tr><td><span class=\"stbadge st-pend\">PreferNoSchedule</span></td><td>stay</td><td>avoided if possible</td></tr>\n<tr><td><span class=\"stbadge st-term\">NoExecute</span></td><td><b>evicted</b></td><td>blocked (unless tolerated)</td></tr>\n</table></div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Remember the direction:</b> taints repel (node → pods); tolerations permit (pod → tainted node). Taints <b>never attract</b> — for that you'd use nodeSelector/affinity (Book 04 in depth).</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch32\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch34\">quiz ▶</a></span><span>Page 36</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">QUIZ</span><h2 id=\"self-check-quiz\">✅ Self-Check Quiz</h2><span class=\"dbadge\">☑ 10 questions</span></div>\n<div class=\"qz\"><span class=\"qn\">Q1.</span>A Kubernetes cluster consists of…<br /><b>A.</b> API Server + etcd only   <b>B.</b> Control Plane + Worker Nodes   <b>C.</b> Nodes + Pods only   <b>D.</b> Masters only</div>\n<div class=\"qz\"><span class=\"qn\">Q2.</span>Which component is the ONLY door to the cluster — everyone talks through it?<br /><b>A.</b> etcd   <b>B.</b> Scheduler   <b>C.</b> API Server   <b>D.</b> kubelet</div>\n<div class=\"qz\"><span class=\"qn\">Q3.</span>A worker dies running 1 of 3 Deployment replicas. What happens?<br /><b>A.</b> Nothing until you fix the node   <b>B.</b> Replica count drops to 2   <b>C.</b> A replacement Pod is created on a healthy node   <b>D.</b> The whole Deployment restarts</div>\n<div class=\"qz\"><span class=\"qn\">Q4.</span>With 5 Control-Plane nodes, how many can fail before etcd loses quorum?<br /><b>A.</b> 1   <b>B.</b> 3   <b>C.</b> 2   <b>D.</b> 4</div>\n<div class=\"qz\"><span class=\"qn\">Q5.</span><code>kubectl get nodes -n dev</code> returns…<br /><b>A.</b> dev's nodes   <b>B.</b> an error   <b>C.</b> nothing   <b>D.</b> all nodes — nodes are cluster-scoped, the flag is ignored</div>\n<div class=\"qz\"><span class=\"qn\">Q6.</span>You delete a ReplicaSet-owned Pod. Result?<br /><b>A.</b> Gone forever   <b>B.</b> Recreated with a new name   <b>C.</b> Same Pod restarts   <b>D.</b> ReplicaSet is deleted too</div>\n<div class=\"qz\"><span class=\"qn\">Q7.</span>Pod stuck in <code>ImagePullBackOff</code>. Most likely cause?<br /><b>A.</b> Bad/typo image tag or missing registry credentials   <b>B.</b> App crashed   <b>C.</b> No CPU available   <b>D.</b> Service misconfigured</div>\n<div class=\"qz\"><span class=\"qn\">Q8.</span>Valid NodePort range?<br /><b>A.</b> 1024–65535   <b>B.</b> 1–1024   <b>C.</b> 8080–9999   <b>D.</b> 30000–32767</div>\n<div class=\"qz\"><span class=\"qn\">Q9.</span>kube-proxy's actual job?<br /><b>A.</b> Forward packets between nodes   <b>B.</b> Assign Pod IPs   <b>C.</b> Watch Services/Endpoints and program node routing rules   <b>D.</b> Run CoreDNS</div>\n<div class=\"qz\"><span class=\"qn\">Q10.</span>Which taint effect <b>evicts existing</b> non-tolerating Pods?<br /><b>A.</b> NoExecute   <b>B.</b> NoSchedule   <b>C.</b> PreferNoSchedule   <b>D.</b> EvictOnly</div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch33\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch35\">answers ▶</a></span><span>Page 37</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">KEY</span><h2 id=\"answer-key-scoring\">🗝️ Answer Key + Scoring</h2><span class=\"dbadge\">grade yourself</span></div>\n<div class=\"table-scroll\"><table>\n<tr><th>Q</th><th>Ans</th><th>Why — one line</th></tr>\n<tr><td>1</td><td><b>B</b></td><td>Cluster = Control Plane (decides) + Workers (execute) — CH 01</td></tr>\n<tr><td>2</td><td><b>C</b></td><td>API Server is the only door; only it touches etcd — CH 02/04</td></tr>\n<tr><td>3</td><td><b>C</b></td><td>Desired 3 ≠ Actual 2 → reconciliation creates a replacement — CH 06/16</td></tr>\n<tr><td>4</td><td><b>C</b></td><td>Quorum of 5 = 3 → tolerate floor(5/2) = 2 failures — CH 08</td></tr>\n<tr><td>5</td><td><b>D</b></td><td>Nodes are cluster-scoped; <code>-n</code> is silently ignored — CH 11</td></tr>\n<tr><td>6</td><td><b>B</b></td><td>Ownership means the promise survives; new name each time — CH 15/16</td></tr>\n<tr><td>7</td><td><b>A</b></td><td>Pull failed: bad tag or private registry without credentials — CH 23</td></tr>\n<tr><td>8</td><td><b>D</b></td><td>30000–32767, auto-assigned if omitted — CH 25</td></tr>\n<tr><td>9</td><td><b>C</b></td><td>Watch &amp; program iptables/IPVS — never forwards traffic itself — CH 27</td></tr>\n<tr><td>10</td><td><b>A</b></td><td>NoExecute evicts now; NoSchedule/Prefer only block placement — CH 33</td></tr>\n</table></div>\n<div class=\"grid3\">\n<div class=\"card center\"><div>🏆</div><p><b>9–10</b><br />Exam-ready on this material</p></div>\n<div class=\"card center\"><div>📖</div><p><b>6–8</b><br />Re-read the missed chapters' 🔑 boxes</p></div>\n<div class=\"card center\"><div>🔁</div><p><b>&lt;6</b><br />Re-run the labs — then retake</p></div>\n</div>\n<div class=\"callout co-tip\"><span class=\"ico\">💡</span><div><b>Missed Q4 or Q10?</b> Those are the two most common interview traps: quorum math and NoExecute eviction. Missed Q5? The cluster-scoped list (Nodes, PVs, ClusterRoles, Namespaces) is a free exam point — memorize it.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch34\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch36\">next ▶</a></span><span>Page 38</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">GLOSS</span><h2 id=\"glossary\">📚 Glossary</h2><span class=\"dbadge\">🔵 REFERENCE</span></div>\n<div class=\"gl\"><b>Cluster</b> — Control Plane + Worker Nodes managed as one unit.</div>\n<div class=\"gl\"><b>Control Plane</b> — the brain: API Server, etcd, Scheduler, Controllers. Makes decisions; runs no user workloads (by taint).</div>\n<div class=\"gl\"><b>API Server</b> — the only door 🚪. All reads/writes (kubectl, kubelet, controllers) go through it; only it touches etcd.</div>\n<div class=\"gl\"><b>etcd</b> — the cluster's memory 💾. Needs quorum (majority) to write — why production runs 3 or 5 Control Planes.</div>\n<div class=\"gl\"><b>Scheduler</b> — assigns new Pods to Nodes based on resources, taints, affinity.</div>\n<div class=\"gl\"><b>Controller</b> — reconciliation loop: watch actual vs desired, act to close the gap.</div>\n<div class=\"gl\"><b>kubelet</b> — the node agent 👷. Talks to the API Server, runs Pods via the runtime, reports status.</div>\n<div class=\"gl\"><b>Container Runtime</b> — pulls images and runs containers (containerd, CRI-O).</div>\n<div class=\"gl\"><b>kube-proxy</b> — watches Services/Endpoints, programs iptables/IPVS rules per node. Never forwards packets itself.</div>\n<div class=\"gl\"><b>Pod</b> — smallest deployable unit: 1+ containers sharing IP, volumes, lifecycle.</div>\n<div class=\"gl\"><b>ReplicaSet</b> — the guarantor: keeps N matching-labeled Pods alive via a template.</div>\n<div class=\"gl\"><b>Deployment</b> — manages ReplicaSets to enable versioned, zero-downtime rollouts and rollbacks.</div>\n<div class=\"gl\"><b>Namespace</b> — logical partition of names + RBAC + quotas inside one cluster. Apartments, not buildings.</div>\n<div class=\"gl\"><b>Service</b> — stable virtual IP + DNS name in front of a changing set of Pods.</div>\n<div class=\"gl\"><b>NodePort</b> — Service type opening one high port (30000–32767) on every node.</div>\n<div class=\"gl\"><b>Taint / Toleration</b> — node-side repulsion / pod-side permission. NoSchedule blocks placement; NoExecute also evicts.</div>\n<div class=\"callout co-key\"><span class=\"ico\">🔑</span><div><b>Self-test the glossary:</b> cover the right side, read each term, say the one-line definition aloud. If you can't — that's tonight's reading.</div></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch35\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch37\">next ▶</a></span><span>Page 39</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">CHEAT</span><h2 id=\"one-page-cheat-sheet\">📄 One-Page Cheat Sheet</h2><span class=\"dbadge\">🔵 print me</span></div>\n<div class=\"grid2\">\n<div class=\"card\"><div class=\"zlabel\">⚙️ Lifecycle</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl create deploy web --image=nginx --replicas=3\n<span class=\"p\">$</span> kubectl get pods -w\n<span class=\"p\">$</span> kubectl scale deploy web --replicas=5\n<span class=\"p\">$</span> kubectl set image deploy/web nginx=nginx:1.26\n<span class=\"p\">$</span> kubectl rollout status|history|undo deploy/web\n<span class=\"p\">$</span> kubectl delete deploy web</div></div>\n<div class=\"card\"><div class=\"zlabel\">🩺 Debug</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl describe pod P  <span class=\"g\"># events at BOTTOM</span>\n<span class=\"p\">$</span> kubectl logs P --previous <span class=\"g\"># crashed container</span>\n<span class=\"p\">$</span> kubectl exec -it P -- sh\n<span class=\"p\">$</span> kubectl get events --sort-by=.lastTimestamp\n<span class=\"g\">Pending→scheduler · ImagePull→registry\nCrashLoop→app</span></div></div>\n</div>\n<div class=\"grid2\">\n<div class=\"card\"><div class=\"zlabel\">🌐 Service types</div><div class=\"table-scroll\"><table><tr><th>Type</th><th>Reach</th></tr><tr><td>ClusterIP</td><td>inside only (VIP + DNS)</td></tr><tr><td>NodePort</td><td>node:30000–32767 from outside</td></tr><tr><td>LoadBalancer</td><td>cloud LB → NodePorts</td></tr></table></div></div>\n<div class=\"card\"><div class=\"zlabel\">🚧 Taints</div><div class=\"term mini\"><span class=\"p\">$</span> kubectl taint node N k=v:NoSchedule\n<span class=\"p\">$</span> kubectl taint node N k=v:NoExecute\n<span class=\"p\">$</span> kubectl taint node N k=v:NoSchedule-<span class=\"g\"> # remove</span>\n<span class=\"g\">tolerations: key/op/value/effect</span></div></div>\n</div>\n<div class=\"card\"><div class=\"zlabel\">🧠 Facts worth a job offer</div>\n<ul>\n<li>Cluster = CP + Workers · API Server is the only door · only it touches etcd</li>\n<li>Quorum: 3 CP → tolerate 1 · <b>2 CP is the worst number</b> · odd counts only</li>\n<li>Namespace partitions <b>names</b>, not hardware · Nodes are cluster-scoped</li>\n<li>Standalone Pod dies = gone · owned Pod dies = replaced (new name)</li>\n<li>Deployment → ReplicaSet(s) → Pods · rollback = new revision, not a rewind</li>\n<li>ClusterIP is a fiction · kube-proxy programs rules, forwards nothing</li>\n<li>One Pod = one IP · containers share localhost, volumes, and fate</li>\n</ul></div>\n<div class=\"center\"><a href=\"#toc\">↑ back to top</a></div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch36\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a> · <a href=\"#ch38\">finale ▶</a></span><span>Page 40</span></div></div>\n\n\n<div class=\"page\"><div class=\"pghead\"><span class=\"chip\">FINALE</span><h2 id=\"the-map-you-can-draw-from-memory\">🗺️ The Map You Can Draw From Memory</h2><span class=\"dbadge\">🎓 graduation</span></div>\n<p>The whole book in one tree. Close this page, draw it on paper, then check yourself.</p>\n<div class=\"mtree\"><b>☸️ CLUSTER</b>\n├── <b>🧠 CONTROL PLANE ×3</b> <span class=\"g\">(quorum)</span>\n│   ├── <u>API Server</u> 🚪 <span class=\"g\">← kubectl · kubelet · controllers · scheduler</span>\n│   ├── <u>etcd</u> 💾 <span class=\"g\">← API Server only</span>\n│   ├── <u>Scheduler</u> 🎯 <span class=\"g\">Pod → Node placement</span>\n│   └── <u>Controllers</u> 🔄 <span class=\"g\">desired ↔ actual, forever</span>\n├── <b>🗂️ NAMESPACES</b> <span class=\"g\">frontend · ai · dev (+ 4 system ns)</span>\n│   └── <u>Deployments → ReplicaSets → Pods 🫛</u> <span class=\"g\">(+ Services · DNS)</span>\n└── <b>💪 WORKERS</b>\n    ├── <u>kubelet</u> 👷 <span class=\"g\">agent ↔ API Server</span>\n    ├── <u>Runtime</u> ⚙️ <span class=\"g\">containers</span>\n    └── <u>kube-proxy</u> 🌐 <span class=\"g\">VIP rules · DNAT · never forwards</span></div>\n<h3 id=\"you-can-now\">✅ You can now…</h3>\n<ul>\n<li>Draw the two halves and name all 7 components with one verb each</li>\n<li>Explain self-healing as a <b>reconciliation loop</b>, not magic</li>\n<li>Do the quorum math and say why 2 Control Planes are the worst number</li>\n<li>Trace <code>nginx:1.25 → 1.26 → broken → undo</code> through the ReplicaSet versions</li>\n<li>Narrate one packet: DNS → VIP → DNAT → Pod → conntrack → home</li>\n<li>Taint a node, watch a Pod go Pending, write the toleration that rescues it</li>\n</ul>\n<div class=\"callout co-key\"><span class=\"ico\">🎓</span><div><b>Where to next:</b> ConfigMaps · Secrets &amp; RBAC (Book 02) · Services deep-dive &amp; Ingress (Book 03) · Taints &amp; scheduling in full (Book 04). The spine you just learned is the same spine in every one of them.</div></div>\n<div class=\"center\">— End of Book 01 · 🎬 —</div>\n<div class=\"pgfoot\"><span>📘 The Complete Kubernetes Guide</span><span><a href=\"#ch37\">◀ prev</a> · <a href=\"#toc\">▤ TOC</a></span><span>Page 41</span></div></div>\n\n\n","toc":[{"id":"the-completekubernetes-guide","text":"THE COMPLETEKUBERNETES GUIDE","level":1},{"id":"contents-click-any-row","text":"Contents — click any row","level":2},{"id":"contents-continued","text":"Contents — continued","level":2},{"id":"what-is-kubernetes","text":"☸️ What is Kubernetes?","level":2},{"id":"the-problem-it-solves-running-one-container-is-easy-running-a-fleet-is-not","text":"🤔 The problem it solves — running ONE container is easy; running a fleet is not","level":3},{"id":"what-s-in-the-box","text":"🎁 What's in the box","level":3},{"id":"what-is-kubernetes-continued","text":"☸️ What is Kubernetes? — continued","level":2},{"id":"what-is-a-kubernetes-cluster","text":"☸️ What is a Kubernetes Cluster?","level":2},{"id":"think-of-it-as","text":"🧠 + 💪 Think of it as:","level":3},{"id":"the-control-plane-master","text":"🧠 The Control Plane (Master)","level":2},{"id":"inside-the-control-plane","text":"🧩 Inside the Control Plane","level":3},{"id":"example-you-tell-kubernetes","text":"🧪 Example — you tell Kubernetes:","level":3},{"id":"the-worker-node","text":"💪 The Worker Node","level":2},{"id":"pods-on-a-worker","text":"🫛 Pods on a Worker","level":3},{"id":"what-s-inside-a-typical-worker-node","text":"🧰 What's inside a typical Worker Node","level":3},{"id":"how-master-amp-worker-communicate","text":"📡 How Master &amp; Worker Communicate","level":2},{"id":"walkthrough-deploying-nginx","text":"🚀 Walkthrough — Deploying nginx","level":2},{"id":"the-flow","text":"🌊 The flow","level":3},{"id":"self-healing-when-a-worker-dies","text":"🔄 Self-Healing — When a Worker Dies","level":2},{"id":"after-reconciliation","text":"✅ After reconciliation","level":3},{"id":"can-the-control-plane-also-be-a-worker","text":"🤔 Can the Control Plane also be a Worker?","level":2},{"id":"master-worker-ratio-amp-etcd-quorum","text":"🗳️ Master : Worker Ratio &amp; etcd Quorum","level":2},{"id":"the-diagram-map-learning-roadmap","text":"🗺️ The Diagram Map + Learning Roadmap","level":2},{"id":"the-learning-order-that-works","text":"🛤️ The learning order that works","level":3},{"id":"namespaces-the-big-idea","text":"🗂️ Namespaces — The Big Idea","level":2},{"id":"when-namespaces-shine","text":"When namespaces shine","level":3},{"id":"names-are-scoped-the-three-superpowers","text":"🏷️ Names Are Scoped + The Three Superpowers","level":2},{"id":"the-three-superpowers-namespaces-unlock","text":"⚡ The three superpowers namespaces unlock","level":3},{"id":"service-dns-default-namespaces","text":"🧭 Service DNS + Default Namespaces","level":2},{"id":"how-pods-find-each-other-dns","text":"📫 How Pods find each other: DNS","level":3},{"id":"the-namespaces-you-always-have","text":"📦 The namespaces you always have","level":3},{"id":"the-complete-namespace-picture","text":"🏢 The Complete Namespace Picture","level":2},{"id":"replicaset-what-is-it","text":"🛡️ ReplicaSet — What Is It?","level":2},{"id":"how-it-counts","text":"🔍 How it \"counts\"","level":3},{"id":"labels-death-amp-why-deployment","text":"💀 Labels, Death &amp; Why Deployment","level":2},{"id":"so-why-isn-t-replicaset-enough-the-ownership-chain","text":"🪆 So why isn't ReplicaSet enough? The ownership chain","level":3},{"id":"the-pod-lifecycle-owned-vs-standalone","text":"👀 The Pod Lifecycle — Owned vs Standalone","level":2},{"id":"what-we-just-proved","text":"🧾 What we just proved","level":3},{"id":"kubectl-the-command-map","text":"⌨️ kubectl — The Command Map","level":2},{"id":"pod-deep-dive","text":"🫛 Pod Deep Dive","level":2},{"id":"multi-container-pods","text":"👥 Multi-Container Pods","level":2},{"id":"good-vs-bad-pod-mates","text":"⚖️ Good vs bad Pod-mates","level":3},{"id":"deployment-rolling-updates","text":"🎞️ Deployment — Rolling Updates","level":2},{"id":"what-actually-happened","text":"🪆 What actually happened","level":3},{"id":"rollout-commands","text":"⏪ Rollout Commands","level":2},{"id":"yaml-anatomy-the-two-specs","text":"📜 YAML Anatomy — The Two Specs","level":2},{"id":"the-two-specs-mystery-deployment","text":"🪆 The Two-Specs Mystery (Deployment)","level":3},{"id":"debugging-1-reading-pod-states","text":"🩺 Debugging 1 — Reading Pod States","level":2},{"id":"debugging-2-the-toolbox","text":"🧰 Debugging 2 — The Toolbox","level":2},{"id":"the-4-step-playbook-in-order","text":"🎯 The 4-step playbook (in order)","level":3},{"id":"nodeport-the-side-entrance","text":"🚪 NodePort — The Side Entrance","level":2},{"id":"service-networking-the-virtual-ip","text":"🎭 Service Networking — The Virtual IP","level":2},{"id":"kube-proxy-s-real-job","text":"🕸️ kube-proxy's Real Job","level":2},{"id":"the-rules-it-writes-iptables-dnat","text":"🪄 The rules it writes (iptables + DNAT)","level":3},{"id":"following-one-packet-6-steps","text":"📦 Following ONE Packet — 6 Steps","level":2},{"id":"observe-vs-control","text":"🔬 Observe vs Control","level":2},{"id":"scale-amp-self-healing","text":"📏 Scale &amp; Self-Healing","level":2},{"id":"namespaces","text":"🗂️ Namespaces","level":2},{"id":"rollout-amp-rollback","text":"🎞️ Rollout &amp; Rollback","level":2},{"id":"taints-amp-tolerations","text":"🚧 Taints &amp; Tolerations","level":2},{"id":"self-check-quiz","text":"✅ Self-Check Quiz","level":2},{"id":"answer-key-scoring","text":"🗝️ Answer Key + Scoring","level":2},{"id":"glossary","text":"📚 Glossary","level":2},{"id":"one-page-cheat-sheet","text":"📄 One-Page Cheat Sheet","level":2},{"id":"the-map-you-can-draw-from-memory","text":"🗺️ The Map You Can Draw From Memory","level":2},{"id":"you-can-now","text":"✅ You can now…","level":3}],"words":8681,"assets":[]};